import json
import time
import urllib.request
import urllib.error

RETRYABLE = (429, 500, 502, 503, 504)  # rate limit or server blew up


class ChatClient:
    """talks to any openai-compatible /v1/chat/completions endpoint."""

    def __init__(self, base_url, api_key, model, timeout=120,
                 retries=3, backoff=1.0, temperature=None,
                 max_tokens=None, seed=None, trace_file=None):
        self.url = base_url.rstrip("/") + "/chat/completions"
        self.api_key = api_key
        self.model = model
        self.timeout = timeout
        self.retries = retries
        self.backoff = backoff
        self.temperature = temperature
        self.max_tokens = max_tokens
        self.seed = seed
        self.trace_file = trace_file
        # agentrouter's waf blocks plain script clients, so send the
        # documented client headers when pointed at it
        self.extra_headers = {}
        if "agentrouter.org" in base_url:
            self.extra_headers = {
                "Originator": "codex_cli_rs",
                "Version": "0.101.0",
                "User-Agent": ("codex_cli_rs/0.101.0 "
                               "(Windows NT 10.0; Win64; x64)"),
            }

    def _headers(self):
        headers = {
            "Content-Type": "application/json",
            "Authorization": "Bearer " + self.api_key,
        }
        headers.update(self.extra_headers)
        return headers

    def _trace(self, record):
        # raw request/response pairs, one json object per line.
        # the api key is never in the body, only in the header,
        # which is not recorded.
        if not self.trace_file:
            return
        try:
            with open(self.trace_file, "a") as f:
                f.write(json.dumps(record) + "\n")
        except OSError:
            pass

    def _body(self, messages, tools=None, stop=None):
        # request body, sampling params only included when set
        body = {
            "model": self.model,
            "messages": messages,
        }
        if tools:
            body["tools"] = tools
            body["tool_choice"] = "auto"
        if self.temperature is not None:
            body["temperature"] = self.temperature
        if self.max_tokens is not None:
            body["max_tokens"] = self.max_tokens
        if self.seed is not None:
            body["seed"] = self.seed
        if stop:
            body["stop"] = stop
        return body

    def _post(self, req):
        # one post with retries on rate limits and server errors
        for attempt in range(self.retries + 1):
            try:
                return urllib.request.urlopen(req, timeout=self.timeout)
            except urllib.error.HTTPError as e:
                last = attempt == self.retries
                if e.code not in RETRYABLE or last:
                    detail = e.read().decode(errors="replace")[:500]
                    raise RuntimeError("api error %d after %d attempt(s): %s"
                                       % (e.code, attempt + 1, detail))
                time.sleep(self.backoff * (2 ** attempt))

    def chat(self, messages, tools=None, stop=None):
        body = self._body(messages, tools, stop=stop)

        req = urllib.request.Request(
            self.url,
            data=json.dumps(body).encode(),
            headers=self._headers(),
            method="POST",
        )
        resp = self._post(req)
        try:
            payload = json.load(resp)
        finally:
            resp.close()

        msg = payload["choices"][0]["message"]
        out = {"role": "assistant"}
        self._trace({"request": body, "response": payload})
        usage = payload.get("usage") or {}
        if usage:
            out["usage"] = {
                "prompt_tokens": usage.get("prompt_tokens", 0),
                "completion_tokens": usage.get("completion_tokens", 0),
            }
        if msg.get("content"):
            out["content"] = msg["content"]
        # thinking models return reasoning_content and require it
        # passed back verbatim on the next turn
        if msg.get("reasoning_content"):
            out["reasoning_content"] = msg["reasoning_content"]
        if msg.get("tool_calls"):
            out["tool_calls"] = [
                {
                    "id": tc["id"],
                    # keep the type tag: strict gateways reject the
                    # echoed assistant message without it
                    "type": "function",
                    "function": {
                        "name": tc["function"]["name"],
                        "arguments": tc["function"].get("arguments") or "{}",
                    },
                }
                for tc in msg["tool_calls"]
            ]
        return out

    def chat_stream(self, messages, tools=None, on_token=None, stop=None):
        # same as chat() but reads server-sent events, calling
        # on_token(text) for each content chunk as it arrives
        body = self._body(messages, tools, stop=stop)
        body["stream"] = True
        # ask the server to send token counts in the last chunk
        body["stream_options"] = {"include_usage": True}

        req = urllib.request.Request(
            self.url,
            data=json.dumps(body).encode(),
            headers=self._headers(),
            method="POST",
        )
        resp = self._post(req)

        content_parts = []
        reasoning_parts = []
        tool_calls = {}
        usage = None
        try:
            for raw in resp:
                line = raw.decode("utf-8", errors="replace").strip()
                if not line.startswith("data:"):
                    continue
                data = line[5:].strip()
                if data == "[DONE]":
                    break
                try:
                    chunk = json.loads(data)
                except json.JSONDecodeError:
                    continue
                # some servers send data: null keepalives
                if not isinstance(chunk, dict):
                    continue
                if "usage" in chunk:
                    usage = chunk["usage"]
                choices = chunk.get("choices") or [{}]
                delta = choices[0].get("delta") or {}
                text = delta.get("content")
                if text:
                    content_parts.append(text)
                    if on_token:
                        on_token(text)
                # thinking-mode deltas carry reasoning separately
                reasoning = delta.get("reasoning_content")
                if reasoning:
                    reasoning_parts.append(reasoning)
                # tool calls arrive in pieces, one index at a time
                for tc in delta.get("tool_calls") or []:
                    idx = tc.get("index", 0)
                    entry = tool_calls.setdefault(
                        idx, {"id": None, "name": None, "arguments": ""})
                    if tc.get("id"):
                        entry["id"] = tc["id"]
                    fn = tc.get("function") or {}
                    if fn.get("name"):
                        entry["name"] = fn["name"]
                    if fn.get("arguments"):
                        entry["arguments"] += fn["arguments"]
        finally:
            resp.close()

        out = {"role": "assistant"}
        if usage:
            out["usage"] = {
                "prompt_tokens": usage.get("prompt_tokens", 0),
                "completion_tokens": usage.get("completion_tokens", 0),
            }
        content = "".join(content_parts)
        if content:
            out["content"] = content
        reasoning = "".join(reasoning_parts)
        if reasoning:
            out["reasoning_content"] = reasoning
        if tool_calls:
            out["tool_calls"] = [
                {
                    "id": e["id"] or "call_%d" % i,
                    # keep the type tag: strict gateways reject the
                    # echoed assistant message without it
                    "type": "function",
                    "function": {
                        "name": e["name"] or "",
                        "arguments": e["arguments"] or "{}",
                    },
                }
                for i, e in sorted(tool_calls.items())
            ]
        self._trace({"request": body, "response": out})
        return out

contents.config.py:
"""defaults from mule.json: ./mule.json wins over ~/.config/mule/mule.json."""
import json
import os

KEYS = ("model", "base_url", "api_key", "max_steps", "timeout", "root",
        "retries", "context_budget", "ask", "reflect", "verbose",
        "parallel_tools", "readonly", "no_network", "allow_tools",
        "deny_tools", "fallback_model", "max_tools", "time_limit",
        "temperature")
HOME_CONFIG = os.path.expanduser("~/.config/mule/mule.json")
LOCAL_CONFIG = "mule.json"


def _read(path):
    try:
        with open(path) as f:
            data = json.load(f)
    except (OSError, ValueError):
        return {}
    if not isinstance(data, dict):
        return {}
    return {k: data[k] for k in KEYS if k in data}


def _read_raw(path):
    # the unfiltered file, for validation
    try:
        with open(path) as f:
            data = json.load(f)
    except (OSError, ValueError):
        return {}
    return data if isinstance(data, dict) else {}


SCHEMA = {
    "model": str, "base_url": str, "api_key": str, "root": str,
    "max_steps": int, "timeout": (int, float), "retries": int,
    "context_budget": int, "ask": bool, "reflect": bool,
    "verbose": bool, "parallel_tools": bool, "readonly": bool,
    "no_network": bool, "allow_tools": str, "deny_tools": str,
    "fallback_model": str, "max_tools": int,
    "time_limit": (int, float), "temperature": (int, float),
    "log_file": str, "trace": str, "tool_timeout": (int, float),
}


def _want_name(want):
    if want is str:
        return "a string"
    if want is int:
        return "an integer"
    if want is bool:
        return "true or false"
    return "a number"


def validate_config(data, source="config"):
    # human-readable problems: unknown keys, wrong value types
    problems = []
    for key in sorted(data):
        want = SCHEMA.get(key)
        if want is None:
            problems.append(
                "unknown key %r in %s (known keys: %s)"
                % (key, source, ", ".join(sorted(SCHEMA))))
            continue
        value = data[key]
        ok = isinstance(value, want)
        if want is int and isinstance(value, bool):
            ok = False  # True is an int in python, not here
        if not ok:
            problems.append(
                "key %r in %s should be %s, got %s"
                % (key, source, _want_name(want),
                   type(value).__name__))
    return problems


def config_problems():
    # validate both config files, naming the file in each problem
    problems = []
    for path in (HOME_CONFIG, LOCAL_CONFIG):
        raw = _read_raw(path)
        if raw:
            problems.extend(validate_config(raw, source=path))
    return problems


def _write(path, data):
    # write the known keys back, sorted, for a stable file
    folder = os.path.dirname(path)
    if folder:
        os.makedirs(folder, exist_ok=True)
    with open(path, "w") as f:
        json.dump({k: data[k] for k in KEYS if k in data},
                  f, indent=2, sort_keys=True)
        f.write("\n")


def load_config():
    # home config first, local mule.json overrides it
    cfg = _read(HOME_CONFIG)
    cfg.update(_read(LOCAL_CONFIG))
    return cfg


def config_path(global_=False):
    return HOME_CONFIG if global_ else LOCAL_CONFIG


def config_list(global_=False):
    return _read(config_path(global_))


def config_get(key, global_=False):
    if key not in KEYS:
        raise KeyError("unknown config key: %s (try: %s)"
                       % (key, ", ".join(KEYS)))
    return config_list(global_).get(key)


def config_set(key, value, global_=False):
    # "40" becomes 40, "true" becomes True, the rest stays a string
    if key not in KEYS:
        raise KeyError("unknown config key: %s (try: %s)"
                       % (key, ", ".join(KEYS)))
    try:
        value = json.loads(value)
    except (ValueError, TypeError):
        pass
    data = config_list(global_)
    data[key] = value
    _write(config_path(global_), data)
    return value


def config_unset(key, global_=False):
    if key not in KEYS:
        raise KeyError("unknown config key: %s (try: %s)"
                       % (key, ", ".join(KEYS)))
    data = config_list(global_)
    data.pop(key, None)
    _write(config_path(global_), data)


def profile_dir():
    d = os.path.join(os.path.expanduser("~"), ".mule", "profiles")
    os.makedirs(d, exist_ok=True)
    return d


def list_profiles():
    d = profile_dir()
    return sorted(f[:-5] for f in os.listdir(d) if f.endswith(".json"))


def load_profile(name):
    # ~/.mule/profiles/NAME.json, merged over config, under cli flags
    path = os.path.join(profile_dir(), name + ".json")
    if not os.path.isfile(path):
        avail = list_profiles()
        hint = ", ".join(avail) if avail else "(none yet)"
        raise ValueError("no such profile: %s. available: %s" % (name, hint))
    try:
        with open(path) as f:
            data = json.load(f)
    except ValueError:
        raise ValueError("profile %s is not valid json" % name)
    if not isinstance(data, dict):
        raise ValueError("profile %s must be a json object" % name)
    return {k: data[k] for k in KEYS if k in data}

