"""plugin tools: ~/.mule/plugins/*.py exposing get_tools()."""
import importlib.util
import os


def plugin_dir():
    d = os.path.join(os.path.expanduser("~"), ".mule", "plugins")
    os.makedirs(d, exist_ok=True)
    return d


def _load_one(name, path):
    # import the file, call get_tools(), validate the shape
    spec = importlib.util.spec_from_file_location(
        "mule_plugin_" + name, path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    get_tools = getattr(mod, "get_tools", None)
    if not callable(get_tools):
        raise ValueError("no get_tools() function")
    raw = get_tools()
    if not isinstance(raw, list):
        raise ValueError("get_tools() must return a list")
    out = []
    for t in raw:
        if not isinstance(t, dict):
            raise ValueError("each tool must be a dict")
        for key in ("name", "description", "handler"):
            if key not in t:
                raise ValueError("tool missing %r" % key)
        if not callable(t["handler"]):
            raise ValueError("tool %r handler is not callable"
                             % (t.get("name"),))
        params = t.get("parameters") or {}
        if not isinstance(params, dict):
            raise ValueError("tool %r parameters must be a dict"
                             % (t.get("name"),))
        out.append({
            "name": str(t["name"]),
            "description": str(t["description"]),
            "parameters": {k: str(v) for k, v in params.items()},
            "run": t["handler"],
        })
    return out


def load_plugins():
    # returns ([tool dicts], [error strings]). a bad plugin never
    # takes down startup, it just shows up in errors.
    tools, errors = [], []
    d = plugin_dir()
    for fname in sorted(os.listdir(d)):
        if not fname.endswith(".py") or fname.startswith("_"):
            continue
        name = fname[:-3]
        try:
            tools.extend(_load_one(name, os.path.join(d, fname)))
        except Exception as e:
            errors.append("plugin %s failed to load: %s" % (name, e))
    return tools, errors

contents.repl.py:
"""interactive loop: type follow-up tasks, slash commands for the rest."""

import os
import re
import subprocess

from cost import cost_for, fmt_cost
from ui import dim, G

HELP_TEXT = """slash commands:
  /help        show this help
  /quit        exit the loop
  /clear       reset the conversation history
  /save NAME   save the session to ~/.mule/sessions/
  /cost        show tokens and spend so far
  /tools       list available tools
  /tools off NAME   disable a tool for this session
  /tools on NAME    re-enable a tool
  /model [NAME]    show or switch the model
  /retry       run the last task again
  /compress    summarize history into a short recap
  /undo        restore the most recently changed file
  /bug [TEXT]  print a prefilled github issue url
extras:
  !CMD         run a shell command directly, no agent involved
  @PATH        attach a file's contents to your task
tip: wrap input in ``` blocks for multiline tasks"""


# @path or @"my file.py": pulled from the project root, dropped
# into a code fence before the task runs. missing files and
# paths escaping the root are left alone.
_AT_RE = re.compile(r"(?<!\S)@(\"[^\"\n]+\"|'[^'\n]+'|[\w.\-\\/]+)")


def expand_at_refs(line, root):
    def _put(m):
        path = m.group(1).strip("\"'")
        full = os.path.normpath(os.path.join(root, path))
        if not full.startswith(os.path.abspath(root) + os.sep):
            return m.group(0)
        if not os.path.isfile(full):
            return m.group(0)
        try:
            with open(full, errors="replace") as f:
                content = f.read()
        except OSError:
            return m.group(0)
        if len(content) > 30000:
            content = content[:30000] + "\n... (truncated)"
        return "\n```%s\n%s\n```\n" % (path, content)
    return _AT_RE.sub(_put, line)


def run_shell_line(cmd, write):
    # "!ls -la" from the repl: run it now, show the output,
    # stay in the loop. the agent never sees it.
    cmd = cmd.strip()
    if not cmd:
        write("usage: !COMMAND")
        return
    try:
        p = subprocess.run(cmd, shell=True, capture_output=True,
                           text=True, timeout=180)
    except Exception as e:
        write("error: %s" % e)
        return
    out = ((p.stdout or "") + (p.stderr or "")).rstrip()
    if out:
        write(out)
    if p.returncode:
        write(dim("exit %d" % p.returncode))


def load_commands(commands_dir):
    # .mule/commands/*.md become /name commands, content is the text
    cmds = {}
    if not os.path.isdir(commands_dir):
        return cmds
    for fname in sorted(os.listdir(commands_dir)):
        if not fname.endswith(".md"):
            continue
        name = fname[:-3].strip().lower()
        if not name:
            continue
        with open(os.path.join(commands_dir, fname)) as f:
            cmds[name] = f.read().strip()
    return cmds


def parse_slash(line):
    # "/save foo bar" -> ("save", "foo bar"), "/quit" -> ("quit", "")
    parts = line[1:].split(None, 1)
    cmd = parts[0].lower() if parts else ""
    arg = parts[1].strip() if len(parts) > 1 else ""
    return cmd, arg


def handle_slash(line, ctx):
    # ctx: write, tools, totals, model, save_fn, commands
    # returns "quit" to leave, "clear" to reset history,
    # ("run", text) to run a custom command as the next task, else None
    write = ctx["write"]
    commands = ctx.get("commands") or {}
    cmd, arg = parse_slash(line)
    if cmd == "help":
        text = HELP_TEXT
        if commands:
            text += ("\ncustom:\n" + "\n".join(
                "  /%s" % n for n in sorted(commands)))
        write(text)
    elif cmd == "quit":
        return "quit"
    elif cmd == "clear":
        return "clear"
    elif cmd == "save":
        if not arg:
            write("usage: /save NAME")
        else:
            write("saved session: %s" % ctx["save_fn"](arg))
    elif cmd == "cost":
        t = ctx["totals"]
        write("tokens: %s in / %s out, cost %s" % (
            "{:,}".format(t["in"]), "{:,}".format(t["out"]),
            fmt_cost(cost_for(ctx["model"], t["in"], t["out"]))))
    elif cmd == "undo":
        write(ctx["tools"].undo_last())
    elif cmd == "model":
        if arg and ctx.get("set_model"):
            ctx["set_model"](arg)
            write("model: %s" % arg)
        elif arg:
            write("model switching is not available here")
        else:
            write("model: %s" % ctx.get("model", "?"))
    elif cmd == "retry":
        last = ctx.get("last_task")
        if last:
            return ("run", last)
        write("nothing to retry yet")
    elif cmd == "compress":
        return "compress"
    elif cmd == "bug":
        from urllib.parse import quote
        title = arg or "bug report"
        body = ("mule version: %s\n\nwhat happened:\n\n"
                "what you expected:\n\nsteps to reproduce:\n"
                % ctx.get("version", "?"))
        url = ("https://github.com/9osiris/mule/issues/new"
               "?title=%s&body=%s" % (quote(title), quote(body)))
        write("file it here:\n%s" % url)
    elif cmd == "tools":
        if arg:
            # /tools off NAME | /tools on NAME
            bits = arg.split(None, 1)
            action = bits[0].lower() if bits else ""
            name = bits[1] if len(bits) > 1 else ""
            if action == "off" and name:
                ctx["tools"].disable_tool(name)
                write("disabled: %s" % name)
            elif action == "on" and name:
                ctx["tools"].enable_tool(name)
                write("enabled: %s" % name)
            else:
                write("usage: /tools [off NAME | on NAME]")
        else:
            names = sorted(n for n in ctx["tools"].tools
                           if n not in ctx["tools"].disabled)
            write("\n".join("  %s - %s" % (n, ctx["tools"].tools[n]["description"])
                            for n in names))
    elif cmd in commands:
        return ("run", commands[cmd])
    else:
        write("unknown command: /%s (try /help)" % cmd)
    return None


def repl_loop(read_line, write, on_task, on_slash, prompt=None,
              root=None):
    # read_line(prompt) raises EOFError/KeyboardInterrupt to leave.
    # the prompt glyph follows the terminal: pretty unicode when
    # it can render, plain > on legacy consoles.
    if prompt is None:
        prompt = G["prompt"] + " "
    # a line starting with ``` opens a multiline block: everything
    # until the closing ``` becomes one task.
    # a line starting with ! runs a shell command directly.
    # @path in a task pulls that file into a code fence first.
    write("interactive mode. /help for commands, /quit to leave. "
          "!cmd runs shell, @file attaches a file.")
    while True:
        try:
            line = read_line(prompt)
        except (EOFError, KeyboardInterrupt):
            write("")
            break
        if line.strip().startswith("```"):
            buf = [line]
            while True:
                try:
                    more = read_line("... ")
                except (EOFError, KeyboardInterrupt):
                    more = "```"
                buf.append(more)
                if more.strip().endswith("```") and len(buf) > 1:
                    break
            line = "\n".join(buf)
        line = line.strip()
        if not line:
            continue
        if line.startswith("!"):
            run_shell_line(line[1:], write)
            continue
        if line.startswith("/"):
            if on_slash(line) == "quit":
                break
            continue
        if root and "@" in line:
            line = expand_at_refs(line, root)
        on_task(line)


def compress_history(chat_fn, messages, track=None):
    # one model call summarizes the conversation, history becomes
    # system prompt plus the recap. keeps long sessions usable.
    reply = chat_fn(messages + [{
        "role": "user",
        "content": "summarize this conversation in under 400 words as "
                   "notes for your future self. keep every key fact, "
                   "decision, file change, and open task.",
    }], [])
    if track:
        track(0, reply.get("usage"))
    summary = reply.get("content") or "(empty summary)"
    system = [m for m in messages if m.get("role") == "system"]
    return system + [{"role": "user",
                      "content": "compressed recap of our work so far:\n"
                                 + summary}]

contents.serve.py:
"""mule serve: a local web chat ui for the mule agent.

one self-contained page (webui.html), no build step, no npm, no
external requests. the backend is stdlib only: ThreadingHTTPServer
plus server-sent events. binds to 127.0.0.1, never 0.0.0.0.
"""
import json
import os
import sys
import threading
import urllib.parse
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

import agent
import sessions
from cost import cost_for, fmt_cost

WEBUI_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                          "webui.html")

_chat_lock = threading.Lock()


class Ctx:
    # everything a request handler needs: parsed args, the api
    # client, the tool set, and the system prompt.
    def __init__(self, args, client, tools, system):
        self.args = args
        self.client = client
        self.tools = tools
        self.system = system
        self.stop = threading.Event()  # set by /api/stop, clears per chat
        self.brand = "mule 3.1"

    def rebuild_tools(self, root):
        # fresh tool set pointed at a new project root, same gates
        from tools import ToolSet
        tools = ToolSet(os.path.abspath(root))
        from plugins import load_plugins
        plugin_tools, _ = load_plugins()
        for t in plugin_tools:
            if t["name"] not in tools.tools:
                tools.tools[t["name"]] = t
        from main import apply_tool_gates
        apply_tool_gates(self.args, tools)
        self.tools = tools


READONLY_TOOLS = ("write_file", "edit_file", "apply_patch", "run_shell")

_SKIP_DIRS = {".git", "node_modules", "__pycache__", ".venv", "venv",
              "dist", "build", ".next", "target"}


def _tree_entries(root, rel=".", depth=0, max_depth=3, cap=400, out=None):
    # flat file listing for the ui sidebar, dirs first, no junk
    if out is None:
        out = []
    if depth > max_depth or len(out) >= cap:
        return out
    full = os.path.join(root, rel)
    try:
        names = sorted(os.listdir(full))
    except OSError:
        return out
    dirs = [n for n in names
            if os.path.isdir(os.path.join(full, n))
            and not n.startswith(".") and n not in _SKIP_DIRS]
    files = [n for n in names
             if not os.path.isdir(os.path.join(full, n))
             and not n.startswith(".")]
    for n in dirs + files:
        if len(out) >= cap:
            break
        p = n if rel == "." else os.path.join(rel, n)
        out.append({"name": n, "path": p.replace(os.sep, "/"),
                    "dir": os.path.isdir(os.path.join(full, n)),
                    "depth": depth})
        if os.path.isdir(os.path.join(full, n)):
            _tree_entries(root, p, depth + 1, max_depth, cap, out)
    return out


def _preview(messages):
    # first user message, squashed to one line for the sidebar
    for m in messages:
        if m.get("role") == "user" and m.get("content"):
            text = " ".join(str(m["content"]).split())
            return text[:60] + ("..." if len(text) > 60 else "")
    return "new chat"


def _public_messages(messages):
    # the transcript the browser needs: user/assistant/tool only,
    # no system prompt, no usage blobs
    out = []
    for m in messages:
        role = m.get("role")
        if role == "user":
            out.append({"role": "user",
                        "content": m.get("content", "")})
        elif role == "assistant":
            out.append({"role": "assistant",
                        "content": m.get("content") or "",
                        "tool_calls": [
                            {"name": c["function"]["name"],
                             "args": c["function"].get("arguments", "")}
                            for c in m.get("tool_calls", [])]})
        elif role == "tool":
            out.append({"role": "tool", "content": m.get("content", "")})
    return out


class Handler(BaseHTTPRequestHandler):
    server_version = "mule-serve/1.0"

    def log_message(self, fmt, *args):
        # one quiet line per request on stderr, not the default
        # dump of every header
        import sys
        sys.stderr.write("serve: %s\n" % (fmt % args))

    def _send(self, code, body, ctype="application/json"):
        if isinstance(body, str):
            body = body.encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", ctype + "; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _json(self, obj, code=200):
        self._send(code, json.dumps(obj))

    def _sse_begin(self):
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream")
        self.send_header("Cache-Control", "no-cache")
        self.send_header("X-Accel-Buffering", "no")
        self.end_headers()

    def _sse_emit(self, obj):
        line = "data: %s\n\n" % json.dumps(obj)
        self.wfile.write(line.encode("utf-8"))
        self.wfile.flush()

    def _path(self):
        return urllib.parse.urlparse(self.path).path

    def _query(self):
        return urllib.parse.parse_qs(
            urllib.parse.urlparse(self.path).query)

    def do_GET(self):
        path = self._path()
        ctx = self.server.ctx
        if path == "/":
            try:
                with open(WEBUI_PATH, "rb") as f:
                    self._send(200, f.read(), "text/html")
            except OSError:
                self._json({"error": "webui.html not found next to "
                                     "serve.py; run mule serve from a "
                                     "source checkout"}, 500)
        elif path == "/api/info":
            self._json({"version": ctx.args.version
                        if hasattr(ctx.args, "version") else "dev",
                        "brand": ctx.brand,
                        "model": ctx.args.model,
                        "base_url": ctx.args.base_url,
                        "root": os.path.abspath(ctx.args.root),
                        "readonly": bool(getattr(ctx.args, "readonly",
                                                 False))})
        elif path == "/api/sessions":
            items = []
            for name in sessions.list_sessions():
                try:
                    msgs = sessions.load_session(name)
                except ValueError:
                    continue
                full = os.path.join(sessions.session_dir(), name + ".jsonl")
                try:
                    mtime = os.path.getmtime(full)
                except OSError:
                    mtime = 0
                items.append({"id": name, "preview": _preview(msgs),
                              "mtime": mtime})
            items.sort(key=lambda x: x["mtime"], reverse=True)
            self._json({"sessions": items})
        elif path == "/api/session":
            sid = self._query().get("id", [None])[0]
            if not sid:
                self._json({"error": "missing id"}, 400)
                return
            try:
                msgs = sessions.load_session(sid)
            except ValueError:
                self._json({"error": "no such session"}, 404)
                return
            self._json({"id": sid,
                        "messages": _public_messages(msgs)})
        elif path == "/api/tree":
            rel = self._query().get("dir", ["."])[0]
            root = os.path.abspath(ctx.args.root)
            full = os.path.abspath(os.path.join(root, rel))
            # paths can't escape the project root
            if full != root and not full.startswith(root + os.sep):
                self._json({"error": "outside project root"}, 400)
                return
            if not os.path.isdir(full):
                self._json({"error": "not a directory"}, 400)
                return
            self._json({"root": root,
                        "entries": _tree_entries(root, os.path.relpath(
                            full, root))})
        else:
            self._json({"error": "not found"}, 404)

    def _body(self):
        length = int(self.headers.get("Content-Length", 0))
        try:
            return json.loads(self.rfile.read(length) or b"{}")
        except (ValueError, OSError):
            return None

    def do_POST(self):
        path = self._path()
        ctx = self.server.ctx
        if path == "/api/chat":
            body = self._body()
            if body is None:
                self._json({"error": "bad json body"}, 400)
                return
            message = (body.get("message") or "").strip()
            if not message:
                self._json({"error": "empty message"}, 400)
                return
            self._handle_chat(message, body.get("session_id"))
        elif path == "/api/session/delete":
            body = self._body()
            if body is None:
                self._json({"error": "bad json body"}, 400)
                return
            sid = body.get("id")
            if not sid:
                self._json({"error": "missing id"}, 400)
                return
            try:
                sessions.delete_session(sid)
            except ValueError:
                self._json({"error": "no such session"}, 404)
                return
            self._json({"ok": True})
        elif path == "/api/session/rename":
            body = self._body()
            if body is None:
                self._json({"error": "bad json body"}, 400)
                return
            sid, name = body.get("id"), (body.get("name") or "").strip()
            if not sid or not name:
                self._json({"error": "missing id or name"}, 400)
                return
            try:
                sessions.rename_session(sid, name)
            except ValueError:
                self._json({"error": "no such session"}, 404)
                return
            self._json({"ok": True, "id": name})
        elif path == "/api/stop":
            ctx.stop.set()
            self._json({"ok": True})
        elif path == "/api/model":
            body = self._body()
            if body is None:
                self._json({"error": "bad json body"}, 400)
                return
            model = (body.get("model") or "").strip()
            if not model:
                self._json({"error": "missing model"}, 400)
                return
            ctx.args.model = model
            ctx.client.model = model
            self._json({"ok": True, "model": model})
        elif path == "/api/root":
            body = self._body()
            if body is None:
                self._json({"error": "bad json body"}, 400)
                return
            root = (body.get("path") or "").strip()
            if not root or not os.path.isdir(root):
                self._json({"error": "not a directory: %s" % root}, 400)
                return
            root = os.path.abspath(root)
            ctx.args.root = root
            try:
                ctx.rebuild_tools(root)
            except Exception as e:
                self._json({"error": "%s" % e}, 500)
                return
            self._json({"ok": True, "root": root})
        elif path == "/api/readonly":
            body = self._body()
            if body is None:
                self._json({"error": "bad json body"}, 400)
                return
            on = bool(body.get("on"))
            for name in READONLY_TOOLS:
                if on:
                    ctx.tools.disable_tool(name)
                else:
                    ctx.tools.enable_tool(name)
            ctx.args.readonly = on
            self._json({"ok": True, "readonly": on})
        else:
            self._json({"error": "not found"}, 404)

    def _handle_chat(self, message, session_id):
        ctx = self.server.ctx
        if not _chat_lock.acquire(blocking=False):
            self._json({"error": "a chat is already running, "
                                 "wait for it to finish"}, 409)
            return
        try:
            self._run_chat(ctx, message, session_id)
        finally:
            _chat_lock.release()

    def _run_chat(self, ctx, message, session_id):
        args = ctx.args
        if session_id:
            try:
                messages = sessions.load_session(session_id)
            except ValueError:
                session_id = None
                messages = None
        else:
            messages = None
        if not session_id:
            session_id = sessions.auto_name()

        self._sse_begin()
        emit = self._sse_emit
        totals = {"in": 0, "out": 0}

        def on_token(t):
            try:
                emit({"type": "token", "text": t})
            except (BrokenPipeError, ConnectionResetError):
                pass

        def chat_fn(msgs, tool_schemas):
            # stream tokens straight into the sse response
            return ctx.client.chat_stream(msgs, tool_schemas,
                                         on_token=on_token)

        def on_result(step, calls, results):
            try:
                emit({"type": "tool", "step": step,
                      "calls": [{"name": c["function"]["name"],
                                 "args": c["function"].get("arguments", "")}
                                for c in calls],
                      "results": results})
            except (BrokenPipeError, ConnectionResetError):
                pass

        def usage_cb(step, usage):
            if usage:
                totals["in"] += usage.get("prompt_tokens", 0)
                totals["out"] += usage.get("completion_tokens", 0)
            # the stop button sets this between steps
            return "user pressed stop" if ctx.stop.is_set() else False

        ctx.stop.clear()
        try:
            out = agent.run(
                message, chat_fn, ctx.tools,
                system_prompt=ctx.system, messages=messages,
                max_steps=args.max_steps, on_result=on_result,
                usage_cb=usage_cb,
                context_budget=getattr(args, "context_budget", 100000))
        except (BrokenPipeError, ConnectionResetError):
            return
        except Exception as e:
            try:
                emit({"type": "error", "message": "%s" % e})
            except (BrokenPipeError, ConnectionResetError):
                pass
            return

        try:
            sessions.save_session(session_id, out)
        except OSError:
            pass
        cost = cost_for(args.model, totals["in"], totals["out"])
        try:
            emit({"type": "done", "session_id": session_id,
                  "answer": agent.last_answer(out),
                  "tokens_in": totals["in"], "tokens_out": totals["out"],
                  "cost": fmt_cost(cost)})
        except (BrokenPipeError, ConnectionResetError):
            pass


def make_server(ctx, port=0):
    # port 0 picks a free one; always localhost, never public
    server = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    server.ctx = ctx
    server.daemon_threads = True
    return server


def cmd_serve(rest):
    # mule serve [--port N] [--no-browser] [--model M] [--root R] ...
    # shares every model/root flag with the normal run.
    from main import parse_args, resolve_system, __version__
    from client import ChatClient
    from ui import red
    port = 8321
    no_browser = False
    rest = list(rest)
    cleaned = []
    i = 0
    while i < len(rest):
        if rest[i] == "--port" and i + 1 < len(rest):
            try:
                port = int(rest[i + 1])
            except ValueError:
                print("error: --port needs a number", file=sys.stderr)
                return 2
            i += 2
        elif rest[i] == "--no-browser":
            no_browser = True
            i += 1
        else:
            cleaned.append(rest[i])
            i += 1
    args = parse_args(cleaned)
    args.version = __version__
    if not args.api_key:
        print(red("set OPENAI_API_KEY or pass --api-key"),
              file=sys.stderr)
        return 2
    client = ChatClient(args.base_url, args.api_key, args.model,
                        timeout=args.timeout, retries=args.retries,
                        temperature=args.temperature,
                        max_tokens=args.max_tokens, seed=args.seed,
                        trace_file=args.trace)
    system = resolve_system(args)
    ctx = Ctx(args, client, None, system)
    ctx.rebuild_tools(args.root)
    server = make_server(ctx, port)
    url = "http://127.0.0.1:%d/" % server.server_address[1]
    print("mule web ui on %s" % url)
    print("local only, close this terminal or ctrl-c to stop")
    if not no_browser:
        import webbrowser
        webbrowser.open(url)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    return 0

