    def schemas(self):
        out = []
        for name, t in self.tools.items():
            if name in self.disabled:
                continue
            props = {k: {"type": "string"} for k in t["parameters"]}
            out.append({
                "type": "function",
                "function": {
                    "name": name,
                    "description": t["description"],
                    # required must be an explicit array: strict
                    # gateways reject the schema when it is missing
                    "parameters": {"type": "object", "properties": props,
                                   "required": list(props)},
                },
            })
        return out

    def disable_tool(self, name):
        # hide a tool from the model and block direct calls
        if name in self.tools:
            self.disabled.add(name)
            return True
        return False

    def enable_tool(self, name):
        self.disabled.discard(name)
        return name in self.tools

    def call(self, name, args):
        tool = self.tools.get(name)
        if not tool:
            return "error: unknown tool '%s'" % name
        if name in self.disabled:
            return "error: tool '%s' is disabled" % name
        try:
            return tool["run"](**{k: v for k, v in args.items()
                                  if k in tool["parameters"]})
        except TypeError as e:
            return "error: bad arguments: %s" % e
        except Exception as e:
            return "error: %s" % e

    # path stays inside the project root or it doesn't happen
    def _resolve(self, path):
        full = os.path.abspath(os.path.join(self.root, path or "."))
        if os.path.commonpath([full, self.root]) != self.root:
            raise ValueError("path escapes project root: %s" % path)
        return full

    def _warn_secrets(self, text, label):
        # file contents go straight to the model, flag credentials loudly
        kind = _matches(SECRET_PATTERNS, text)
        if kind:
            msg = ("warning: %s looks like it contains a %s, "
                   "it is being sent to the model" % (label, kind))
            if self.warn:
                self.warn(msg)
            else:
                print(msg, file=sys.stderr)

    def read_file(self, path):
        full = self._resolve(path)
        if not os.path.isfile(full):
            return "error: no such file: %s" % path
        with open(full, "r", errors="replace") as f:
            data = f.read(MAX_READ + 1)
        if len(data) > MAX_READ:
            data = data[:MAX_READ] + "\n...[truncated]"
        self._warn_secrets(data, path)
        return data

    def undo_last(self):
        # restore the most recently changed file, for /undo and --undo
        restored = self.backups.undo_last()
        if restored is None:
            return "nothing to undo"
        return "restored %s" % os.path.relpath(restored, self.root)

    def _confirm_write(self, action, path, old_text, new_text):
        # in --ask mode, show what the write would change first
        if not self.confirm:
            return True
        prompt = action
        diff = make_diff(old_text, new_text, path)
        if diff:
            from ui import color_diff
            prompt += "\n" + color_diff(diff)
        return self.confirm(prompt)

    def write_file(self, path, content=""):
        full = self._resolve(path)
        content = content or ""
        old_text = ""
        if os.path.isfile(full):
            with open(full, "r", errors="replace") as f:
                old_text = f.read()
        if not self._confirm_write("write_file %s" % path, path,
                                   old_text, content):
            return "declined: the write was not applied"
        if os.path.isfile(full):
            self.backups.stash(full)
        os.makedirs(os.path.dirname(full) or self.root, exist_ok=True)
        with open(full, "w") as f:
            f.write(content)
        return "wrote %d bytes to %s" % (len(content), path)

    def edit_file(self, path, old="", new=""):
        # patch one exact string. must match exactly once or it bails
        full = self._resolve(path)
        if not os.path.isfile(full):
            return "error: no such file: %s" % path
        if not old:
            return "error: old string is empty, nothing to replace"
        with open(full, "r", errors="replace") as f:
            data = f.read()
        count = data.count(old)
        if count == 0:
            return "error: old string not found in %s" % path
        if count > 1:
            return ("error: old string matches %d times in %s, "
                    "be more specific" % (count, path))
        new_data = data.replace(old, new or "", 1)
        if not self._confirm_write("edit_file %s" % path, path,
                                   data, new_data):
            return "declined: the edit was not applied"
        self.backups.stash(full)
        with open(full, "w") as f:
            f.write(new_data)
        return "edited %s" % path

    def list_dir(self, path="."):
        full = self._resolve(path)
        if not os.path.isdir(full):
            return "error: no such directory: %s" % path
        lines = []
        for name in sorted(os.listdir(full)):
            p = os.path.join(full, name)
            if os.path.isdir(p):
                lines.append(name + "/")
            else:
                lines.append("%s (%d bytes)" % (name, os.path.getsize(p)))
        return "\n".join(lines) or "(empty)"

    def run_shell(self, command, timeout="30", background="false"):
        danger = _matches(DANGEROUS, command)
        if danger:
            return "refused: looks like %s, not running it" % danger
        critical = _matches(CRITICAL, command)
        if critical:
            # the point of no return: only a typed "yes" runs it
            if self.confirm_critical and self.confirm_critical(command):
                pass
            else:
                return ("refused: %s needs the literal word 'yes' "
                        "in --ask mode, not running it" % critical)
        elif self.confirm and not self.confirm(command):
            return "declined: the command was not run"
        if str(background).lower() in ("true", "1", "yes"):
            jid = self.jobs.start(command)
            return "job started: %d (use job_output %d to read it)" % (jid, jid)
        try:
            timeout = float(timeout)
        except (TypeError, ValueError):
            timeout = 30
        timeout = min(max(timeout, 1), 300)
        try:
            proc = subprocess.run(
                command, shell=True, cwd=self.root,
                capture_output=True, text=True, timeout=timeout,
            )
        except subprocess.TimeoutExpired:
            return "error: command timed out after %ss" % timeout
        out = (proc.stdout or "") + (proc.stderr or "")
        if len(out) > MAX_OUTPUT:
            out = out[:MAX_OUTPUT] + "\n...[truncated]"
        out = out.rstrip() or "(no output)"
        return "exit %d\n%s" % (proc.returncode, out)

    def jobs_list(self):
        # every background job, newest last, with an output preview
        rows = self.jobs.all()
        if not rows:
            return "(no background jobs)"
        lines = []
        for j in rows:
            status = "done (exit %s)" % j["returncode"] if j["done"] \
                else "running"
            if j["killed"]:
                status += ", killed"
            preview = (j["output"] or "").strip().split("\n")
            preview = " | ".join(preview[:3])[:200]
            lines.append("#%d [%s] %s%s" % (
                j["id"], status, j["command"][:60],
                (" -- " + preview) if preview else ""))
        return "\n".join(lines)

    def job_output(self, id=""):
        # full output of one job, capped like everything else
        try:
            jid = int(id)
        except (TypeError, ValueError):
            return "error: bad job id: %s" % id
        job = self.jobs.get(jid)
        if job is None:
            return "error: no such job: %s" % id
        out = job["output"] or ("(still running)" if not job["done"]
                                else "(no output)")
        if len(out) > MAX_OUTPUT:
            out = out[:MAX_OUTPUT] + "\n...[truncated]"
        state = "done" if job["done"] else "running"
        return "job #%d [%s]\n%s" % (jid, state, out)

    def job_kill(self, id=""):
        try:
            jid = int(id)
        except (TypeError, ValueError):
            return "error: bad job id: %s" % id
        job = self.jobs.get(jid)
        if job is None:
            return "error: no such job: %s" % id
        if job["done"]:
            return "job #%d already finished" % jid
        self.jobs.kill(jid)
        return "killed job #%d" % jid

    def ask_user(self, question="", options="[]"):
        # the model asks the human something mid-run
        if not question:
            return "error: empty question"
        try:
            opts = json.loads(options or "[]")
        except json.JSONDecodeError:
            return "error: options was not valid json"
        if not isinstance(opts, list) or not 2 <= len(opts) <= 4:
            return "error: give 2 to 4 options as a json list"
        opts = [str(o) for o in opts]
        if not self.ask:
            return ("error: cannot ask the user in non-interactive mode, "
                    "proceed with your best guess and say what you assumed")
        try:
            return self.ask(question, opts)
        except Exception as e:
            return "error: asking failed: %s" % e

    def delegate(self, task="", system=""):
        # farm a subtask out to a fresh agent loop with its own history
        if not task:
            return "error: empty task"
        if self.delegate_depth >= 1:
            return "error: delegates cannot spawn their own delegates"
        if not self.make_chat:
            return "error: delegation is not wired up in this run"
        with self._delegate_sem:
            sub = ToolSet(self.root, make_chat=self.make_chat,
                          delegate_depth=self.delegate_depth + 1)
            try:
                messages = _agent_run(task, self.make_chat(), sub,
                                      system_prompt=(system or "").strip()
                                      or None,
                                      max_steps=15)
            except Exception as e:
                return "error: delegate failed: %s" % e
            answer = _agent_last(messages)
            return answer or "(the delegate said nothing)"

    def todo_write(self, todos="[]"):
        # the model rewrites its whole todo list each time it changes
        try:
            items = json.loads(todos or "[]")
        except json.JSONDecodeError:
            return "error: todos was not valid json"
        if not isinstance(items, list):
            return "error: todos must be a json list"
        cleaned = []
        for it in items:
            if not isinstance(it, dict) or not it.get("text"):
                return "error: every todo needs a text field"
            status = it.get("status") or "pending"
            if status not in TODO_STATES:
                return "error: bad status %r, use %s" % (
                    status, "/".join(TODO_STATES))
            cleaned.append({"text": str(it["text"]),
                            "status": status})
        self.todos = cleaned
        return self.progress_line() or "todo list cleared"

    def todo_read(self):
        # the current list, readable at a glance
        if not self.todos:
            return "(no todos)"
        marks = {"pending": "[ ]", "in_progress": "[>]",
                 "done": "[x]"}
        return "\n".join("%s %s" % (marks[t["status"]], t["text"])
                         for t in self.todos)

    def progress_line(self):
        # compact "[2/5] current thing" line for the loop to print
        if not self.todos:
            return None
        done = sum(1 for t in self.todos if t["status"] == "done")
        cur = next((t for t in self.todos
                    if t["status"] == "in_progress"), None)
        if cur is None:
            cur = next((t for t in self.todos
                        if t["status"] == "pending"), None)
        what = cur["text"] if cur else "all done"
        return "[%d/%d] %s" % (done, len(self.todos), what)

    def read_image(self, path):
        # load an image as a data uri, shaped for vision-capable models
        full = self._resolve(path)
        ext = os.path.splitext(full)[1].lower()
        mime = IMAGE_TYPES.get(ext)
        if not mime:
            return "error: not a supported image (png/jpg/gif/webp): %s" % path
        if not os.path.isfile(full):
            return "error: no such file: %s" % path
        size = os.path.getsize(full)
        if size > MAX_IMAGE:
            return "error: image too big (%d bytes, max %d)" % (
                size, MAX_IMAGE)
        with open(full, "rb") as f:
            data = f.read()
        uri = "data:%s;base64,%s" % (
            mime, base64.b64encode(data).decode("ascii"))
        return ("image %s, %d bytes, %s. show it to the user like this:\n"
                "![%s](%s)" % (path, size, mime, path, uri))

    def fetch_url(self, url):
        # grab a page, strip the html down to rough text
        scheme = urllib.parse.urlparse(url or "").scheme
        if scheme not in ("http", "https"):
            return "error: only http and https urls, got: %s" % scheme
        try:
            req = urllib.request.Request(
                url, headers={"User-Agent": "mule/1.0"})
            with urllib.request.urlopen(req, timeout=30) as resp:
                data = resp.read(MAX_FETCH + 1)
        except Exception as e:
            return "error: fetch failed: %s" % e
        if len(data) > MAX_FETCH:
            data = data[:MAX_FETCH]
        text = data.decode("utf-8", errors="replace")
        text = re.sub(r"<script.*?</script>", " ", text,
                      flags=re.S | re.I)
        text = re.sub(r"<style.*?</style>", " ", text, flags=re.S | re.I)
        text = re.sub(r"<[^>]+>", " ", text)
        text = html.unescape(text)
        text = re.sub(r"\s+", " ", text).strip()
        return text or "(empty page)"

    def web_search(self, query="", count="5"):
        # duckduckgo lite search, returns titles, urls, and snippets
        if not query:
            return "error: empty query"
        try:
            n = max(1, min(int(count), 10))
        except (TypeError, ValueError):
            n = 5
        url = DDG_LITE + "?q=" + urllib.parse.quote_plus(query)
        try:
            req = urllib.request.Request(
                url, headers={"User-Agent": "mule/1.0"})
            with urllib.request.urlopen(req, timeout=30) as resp:
                page = resp.read(MAX_FETCH).decode("utf-8",
                                                   errors="replace")
        except Exception as e:
            return "error: search failed: %s" % e
        results = _ddg_results(page, n)
        if not results:
            return "no results for %r" % query
        lines = []
        for i, (title, link, snippet) in enumerate(results, 1):
            lines.append("%d. %s\n   %s" % (i, title, link))
            if snippet:
                lines.append("   %s" % snippet)
        return "\n".join(lines)

    def grep(self, pattern, path=".", glob="*"):
        # walk the tree, print file:line for every line matching
        # the regex. skips binaries, caps at 100 hits.
        try:
            rx = re.compile(pattern or "")
        except re.error as e:
            return "error: bad pattern: %s" % e
        base = self._resolve(path)
        if not os.path.isdir(base):
            return "error: not a directory: %s" % path
        hits = []
        for dirpath, _, files in os.walk(base):
            for name in sorted(files):
                if not fnmatch.fnmatch(name, glob or "*"):
                    continue
                full = os.path.join(dirpath, name)
                rel = os.path.relpath(full, self.root)
                try:
                    with open(full, "r", errors="replace") as f:
                        for i, line in enumerate(f, 1):
                            if "\x00" in line:
                                break  # binary, skip the file
                            if rx.search(line):
                                hits.append("%s:%d: %s"
                                            % (rel, i, line.rstrip()))
                            if len(hits) >= 100:
                                out = "\n".join(hits) + "\n...[truncated]"
                                self._warn_secrets(out, "grep results")
                                return out
                except OSError:
                    continue
        out = "\n".join(hits) or "no matches for %r" % pattern
        self._warn_secrets(out, "grep results")
        return out

    def find(self, pattern="*", path="."):
        # find files by name, glob against the basename
        base = self._resolve(path)
        if not os.path.isdir(base):
            return "error: not a directory: %s" % path
        found = []
        for dirpath, _, files in os.walk(base):
            for name in sorted(files):
                if fnmatch.fnmatch(name, pattern or "*"):
                    found.append(os.path.relpath(
                        os.path.join(dirpath, name), self.root))
                if len(found) >= 100:
                    return "\n".join(found) + "\n...[truncated]"
        return "\n".join(found) or "no files matching %r" % pattern

    def tree(self, path=".", depth="3"):
        # classic tree view, dirs get a trailing slash
        try:
            max_depth = max(1, min(int(depth), 10))
        except (TypeError, ValueError):
            max_depth = 3
        base = self._resolve(path)
        if not os.path.isdir(base):
            return "error: not a directory: %s" % path
        lines = [os.path.basename(base) or base]

        def walk(dirpath, prefix, level):
            if level > max_depth:
                return
            try:
                entries = sorted(os.listdir(dirpath))
            except OSError:
                return
            # dirs first, like the real tree command
            entries.sort(key=lambda e: not os.path.isdir(
                os.path.join(dirpath, e)))
            for i, name in enumerate(entries):
                last = i == len(entries) - 1
                branch = "└── " if last else "├── "
                full = os.path.join(dirpath, name)
                label = name + "/" if os.path.isdir(full) else name
                lines.append(prefix + branch + label)
                if os.path.isdir(full):
                    walk(full, prefix + ("    " if last else "│   "),
                         level + 1)

        walk(base, "", 1)
        return "\n".join(lines)

    def read_many(self, paths="[]"):
        # read a batch of files in one call, capped at 10
        try:
            wanted = json.loads(paths or "[]")
        except ValueError:
            return "error: paths must be a json list"
        if not isinstance(wanted, list):
            return "error: paths must be a json list"
        parts = []
        for p in wanted[:10]:
            full = self._resolve(p)
            if not os.path.isfile(full):
                parts.append("=== %s ===\nerror: no such file" % p)
                continue
            with open(full, "r", errors="replace") as f:
                data = f.read(MAX_READ + 1)
            if len(data) > MAX_READ:
                data = data[:MAX_READ] + "\n...[truncated]"
            self._warn_secrets(data, p)
            parts.append("=== %s ===\n%s" % (p, data))
        return "\n\n".join(parts) or "(no files given)"

    def apply_patch(self, edits="[]"):
        # batch of {path, old, new} edits. every old string must
        # match exactly once, otherwise nothing is written.
        try:
            wanted = json.loads(edits or "[]")
        except ValueError:
            return "error: edits must be a json list"
        if not isinstance(wanted, list) or not wanted:
            return "error: edits must be a non-empty json list"
        staged = []
        for e in wanted:
            path = (e or {}).get("path", "")
            old, new = (e or {}).get("old", ""), (e or {}).get("new", "")
            full = self._resolve(path)
            if not os.path.isfile(full):
                return "error: no such file: %s (nothing applied)" % path
            if not old:
                return "error: empty old string for %s (nothing applied)" % path
            with open(full, "r", errors="replace") as f:
                data = f.read()
            if data.count(old) != 1:
                return ("error: old string matches %d times in %s, "
                        "need exactly 1 (nothing applied)"
                        % (data.count(old), path))
            staged.append((path, full, data.replace(old, new, 1)))
        if self.confirm and not self.confirm(
                "apply_patch: %d edits across %d files"
                % (len(staged), len({p for p, _, _ in staged}))):
            return "declined: the patch was not applied"
        for path, full, data in staged:
            self.backups.stash(full)
            with open(full, "w") as f:
                f.write(data)
        return "applied %d edits" % len(staged)

    def file_info(self, path):
        # quick stat block: type, size, modified time
        full = self._resolve(path or ".")
        if not os.path.exists(full):
            return "error: no such file or directory: %s" % path
        st = os.stat(full)
        kind = "dir" if os.path.isdir(full) else "file"
        when = datetime.datetime.fromtimestamp(
            st.st_mtime).strftime("%Y-%m-%d %H:%M")
        return "path: %s\ntype: %s\nsize: %d bytes\nmodified: %s" % (
            path, kind, st.st_size, when)

    def _git(self, *args):
        # run git in the project root, error when it is not a repo
        try:
            proc = subprocess.run(
                ["git"] + list(args), cwd=self.root,
                capture_output=True, text=True, timeout=30)
        except (OSError, subprocess.TimeoutExpired) as e:
            return "error: git failed: %s" % e
        if proc.returncode != 0:
            return "error: git: %s" % (proc.stderr.strip()
                                       or "not a git repository")
        return proc.stdout.rstrip() or "(no output)"

    def git_status(self):
        return self._git("status", "--short")

    def git_diff(self, path=""):
        args = ["diff", "--"] + ([path] if path else [])
        return self._git(*args)

    def git_log(self, count="10"):
        try:
            n = max(1, min(int(count), 50))
        except (TypeError, ValueError):
            n = 10
        return self._git("log", "--oneline", "-n", str(n))

    def http_post(self, url="", body="{}"):
        # post json somewhere. sending data out is sensitive, so this
        # only runs in --ask mode after an explicit confirmation.
        if not self.confirm:
            return ("error: http_post needs --ask mode, the user must "
                    "confirm every request")
        scheme = urllib.parse.urlparse(url or "").scheme
        if scheme not in ("http", "https"):
            return "error: only http and https urls, got: %s" % scheme
        try:
            payload = json.loads(body or "{}")
        except ValueError:
            return "error: body must be a json string"
        if not self.confirm("http_post %s with body: %s"
                            % (url, json.dumps(payload)[:200])):
            return "declined: the request was not sent"
        try:
            req = urllib.request.Request(
                url, data=json.dumps(payload).encode(),
                headers={"User-Agent": "mule/1.0",
                         "Content-Type": "application/json"})
            with urllib.request.urlopen(req, timeout=30) as resp:
                data = resp.read(MAX_OUTPUT + 1)
        except Exception as e:
            return "error: post failed: %s" % e
        text = data.decode("utf-8", errors="replace")
        if len(data) > MAX_OUTPUT:
            text = text[:MAX_OUTPUT] + "\n...[truncated]"
        return "status %d\n%s" % (resp.status, text or "(empty)")

contents.ui.py:
"""terminal rendering: colors, markdown, tool transcript, spinners.

stdlib at the core. when rich is installed, RichRenderer gives
markdown, syntax highlighting, and live streaming. otherwise
PlainRenderer does a decent job with plain ansi.
pip install rich (or pip install mule[rich]) to upgrade.
"""
import os
import re
import sys
import threading

_enabled = not os.environ.get("NO_COLOR")

# rich is optional. one guarded import, one flag, checked once.
# nothing below imports rich outside this block.
try:
    from rich.console import Console as _RichConsole
    from rich.markdown import Markdown as _RichMarkdown
    from rich.live import Live as _RichLive
    _RICH = True
except ImportError:
    _RICH = False


def _windows_ansi():
    # windows 10+: ask the console to interpret ansi escapes.
    # true when colors will actually render on this terminal.
    if os.name != "nt":
        return True
    try:
        import ctypes
        k = ctypes.windll.kernel32
        h = k.GetStdHandle(-11)
        mode = ctypes.c_ulong()
        if k.GetConsoleMode(h, ctypes.byref(mode)):
            k.SetConsoleMode(h, mode.value | 4)
            return True
    except Exception:
        pass
    return False


def init_color(no_color):
    # call once from main. the flag wins, then the env var.
    # on windows without working ansi, color turns off entirely,
    # so escapes never print as raw text.
    global _enabled
    _enabled = not (no_color or os.environ.get("NO_COLOR"))
    if _enabled and not _windows_ansi():
        _enabled = False
    refresh_glyphs()


def _wrap(code, text):
    if not _enabled or not text:
        return text
    return "\033[%sm%s\033[0m" % (code, text)


def red(text):
    return _wrap("31", text)


def green(text):
    return _wrap("32", text)


def yellow(text):
    return _wrap("33", text)


def bold(text):
    return _wrap("1", text)


def dim(text):
    return _wrap("2", text)


def brand(text):
    # bold amber, the mule color: the mark, panels, the footer rule
    return _wrap("1;33", text)


def cyan(text):
    return _wrap("36", text)


# glyphs: unicode when the terminal can show it, plain ascii on
# legacy consoles (windows cmd) where fancy chars print as boxes.
def _supports_unicode():
    enc = getattr(sys.stdout, "encoding", None) or "utf-8"
    try:
        "\u23fa\u23bf\u276f\u2500\u00b7\u25f7".encode(enc)
        return True
    except Exception:
        return False


UNICODE_OK = _supports_unicode()


def _glyphs():
    if UNICODE_OK:
        return {"call": "\u23fa", "result": "\u23bf",
                "rule": "\u2500", "thin": "\u2504",
                "prompt": "\u276f", "dot": "\u00b7",
                "frames": ["\u25f7", "\u25f6", "\u25f5", "\u25f4"],
                "tl": "\u256d", "tr": "\u256e",
                "bl": "\u2570", "br": "\u256f",
                "v": "\u2502"}
    return {"call": "*", "result": "|",
            "rule": "-", "thin": "-",
            "prompt": ">", "dot": "|",
            "frames": ["|", "/", "-", "\\"],
            "tl": "+", "tr": "+",
            "bl": "+", "br": "+",
            "v": "|"}


G = _glyphs()


def refresh_glyphs(force=None):
    # re-detect, in case stdout changed since import. updates the
    # dict in place so existing imports keep working. force=True
    # or False pins the set, which is what tests use.
    global UNICODE_OK
    UNICODE_OK = _supports_unicode() if force is None else force
    G.clear()
    G.update(_glyphs())


MULE_HEAD = r"""   /\ /\
  / \ / \
  \ \__/ /
   \ ____ /
    \______/"""


# plain markdown rendering, stdlib only

def _inline_md(text):
    # `code` spans are stashed first so * inside them is untouched.
    # then **bold**, then *italic* / _italic_. degrades to plain
    # text when color is off.
    codes = []

    def _stash(m):
        codes.append(cyan(m.group(1)))
        return "\x00%d\x00" % (len(codes) - 1)

    text = re.sub(r"`([^`\n]+)`", _stash, text)
    text = re.sub(r"\*\*([^*]+)\*\*", lambda m: bold(m.group(1)), text)
    text = re.sub(r"(?<!\w)\*([^*]+)\*(?!\w)",
                  lambda m: dim(m.group(1)), text)
    text = re.sub(r"(?<!\w)_([^_]+)_(?!\w)",
                  lambda m: dim(m.group(1)), text)
    for i, c in enumerate(codes):
        text = text.replace("\x00%d\x00" % i, c)
    return text


def render_markdown_plain(text):
    # line-based markdown for terminals without rich: headings,
    # rules, quotes, fenced code, and inline styles. anything
    # unrecognized passes through untouched.
    out = []
    in_fence = False
    for line in str(text).splitlines():
        s = line.strip()
        if s.startswith("```"):
            if not in_fence and s[3:].strip():
                out.append(dim("  -- %s --" % s[3:].strip()))
            in_fence = not in_fence
            continue
        if in_fence:
            out.append("  " + line)
            continue
        if re.match(r"^#{1,6}\s", s):
            out.append(brand(bold(re.sub(r"^#{1,6}\s+", "", s))))
        elif s in ("---", "***", "___"):
            out.append(dim("-" * 40))
        elif s.startswith(">"):
            out.append(dim(s))
        else:
            out.append(_inline_md(line))
    return "\n".join(out)


# tool transcript, one line per call

def args_summary(args):
    # {"path": ".", "x": 1} -> 'path=., x=1', values cut at 60
    return ", ".join("%s=%s" % (k, str(v)[:60])
                     for k, v in (args or {}).items())


def tool_call_line(name, summary=""):
    # one dim line per call: the amber dot, the name, the args.
    # no panel per call, the transcript stays scannable.
    head = "%s %s" % (brand(G["call"]), name)
    if summary:
        one = " ".join(str(summary).split())
        if len(one) > 100:
            one = one[:97] + "..."
        head += " " + dim(one)
    return head


def tool_result_line(text):
    # nested under the call: first line dimmed, "+N lines" when
    # truncated. errors show red so failures jump out.
    text = str(text or "")
    lines = text.splitlines()
    first = lines[0][:120] if lines else "(empty)"
    extra = max(0, len(lines) - 1)
    s = G["result"] + " " + first
    if extra:
        s += " ... +%d lines" % extra
    if text.startswith("error:"):
        return red(s)
    return dim(s)


def tool_panel(name, summary):
    # one tool call as a rounded panel, name in the title bar.
    # kept for scripts that used it; the repl now uses the
    # compact transcript lines above instead.
    rows = [r for r in str(summary or "").splitlines()]
    inner = max([len(name)] + [len(r) for r in rows] + [0])
    w = min(70, max(inner + 4, len(name) + 6, 20))
    top = G["tl"] + G["rule"] + " " + name + " " \
        + G["rule"] * (w - 5 - len(name)) + G["tr"]
    out = [brand(top[:3]) + cyan(name)
           + brand(top[3 + len(name):])]
    for r in rows:
        cell = r[:w - 4] + " " * (w - 4 - len(r[:w - 4]))
        out.append(brand(G["v"] + " ") + cell + brand(" " + G["v"]))
    out.append(brand(G["bl"] + G["rule"] * (w - 2) + G["br"]))
    return "\n".join(out)


def run_banner(version, model, root):
    # non-interactive startup: the mark, then version/model/root
    d = G["dot"]
    return "%s\n  %s" % (
        brand(MULE_HEAD),
        dim("mule %s %s %s %s %s" % (version, d, model, d, root)))


def step_line(step, tokens_in, tokens_out, cost):
    # one dim line per step: number, tokens, cost
    d = G["dot"]
    return dim("  step %d %s %s in / %s out %s %s" % (
        step, d, "{:,}".format(tokens_in),
        "{:,}".format(tokens_out), d, cost))


def _cell(text, width):
    # pad or cut one column cell, plain text only
    text = str(text)[:width]
    return text + " " * (width - len(text))


def welcome_screen(version, model, root, recent, tips):
    # repl welcome: the mark and model on the left, recent
    # sessions and tips on the right. cells are padded as plain text first, then colorized whole, so the
    # columns stay aligned with color on or off.
    w, lw, rw, gap = 76, 32, 38, 4
    title = " mule v%s " % version
    fill = w - len(title)
    lines = [brand(G["thin"] * (fill // 2) + title
                   + G["thin"] * (fill - fill // 2))]
    head = MULE_HEAD.splitlines()
    left = (["", "welcome back.", ""]
            + head
            + ["", "model  " + str(model), "root   " + str(root)])
    right = (["recent activity"]
             + (list(recent)[:4] or ["(no sessions yet)"])
             + ["", "tips"]
             + list(tips)[:3])
    head_rows = set(range(3, 3 + len(head)))
    for i in range(max(len(left), len(right))):
        l = _cell(left[i] if i < len(left) else "", lw)
        r = _cell(right[i] if i < len(right) else "", rw)
        if i in head_rows:
            l = brand(l)
        if (right[i] if i < len(right) else "") in ("recent activity",
                                                    "tips"):
            r = brand(r)
        lines.append("  " + l + " " * gap + r)
    lines.append(brand(G["thin"] * w))
    return "\n".join(lines)


def status_footer(version, model, tokens_in, tokens_out, cost):
    # the end-of-run footer: model, tokens, cost under an amber rule
    return "%s\nmule %s | model %s | %s in / %s out | %s" % (
        brand(G["rule"] * 40), version, model,
        "{:,}".format(tokens_in), "{:,}".format(tokens_out), cost)


class Spinner:
    # one-line spinner while waiting on the model. silent unless
    # stdout is a real terminal, cleared when the reply lands.
    def __init__(self, label="thinking"):
        self.label = label
        self._i = 0
        self._on = False

    def _ok(self):
        return (_enabled and hasattr(sys.stdout, "isatty")
                and sys.stdout.isatty())

    def _frame(self):
        frames = G["frames"]
        return frames[self._i % len(frames)]

    def tick(self):
        if not self._ok():
            return
        frame = self._frame()
        sys.stdout.write("\r%s %s" % (brand(frame), self.label))
        sys.stdout.flush()
        self._i += 1
        self._on = True

    def done(self):
        if self._on and self._ok():
            sys.stdout.write("\r" + " " * (len(self.label) + 4) + "\r")
            sys.stdout.flush()
        self._on = False


class ThreadSpinner:
    # aider-style spinner: start() returns immediately, the first
    # frame appears after delay (fast replies never flicker),
    # stop() clears the line. runs on its own thread.
    def __init__(self, label="thinking", delay=0.5):
        self.label = label
        self.delay = delay
        self._stop = threading.Event()
        self._thread = None

    def _ok(self):
        return (_enabled and hasattr(sys.stdout, "isatty")
                and sys.stdout.isatty())

    def start(self):
        if not self._ok() or self._thread is not None:
            return
        self._stop.clear()
        self._thread = threading.Thread(target=self._spin, daemon=True)
        self._thread.start()

    def _spin(self):
        if self._stop.wait(self.delay):
            return
        i = 0
        frames = G["frames"]
        while not self._stop.is_set():
            frame = frames[i % len(frames)]
            sys.stdout.write("\r%s %s" % (brand(frame), self.label))
            sys.stdout.flush()
            i += 1
            if self._stop.wait(0.1):
                break
        sys.stdout.write("\r" + " " * (len(self.label) + 4) + "\r")
        sys.stdout.flush()

    def stop(self):
        if self._thread is not None:
            self._stop.set()
            self._thread.join(timeout=1)
            self._thread = None


# renderers: plain stdlib vs rich

class _PlainStream:
    # no rich: tokens go straight to the terminal, raw.
    def feed(self, token):
        sys.stdout.write(token)
        sys.stdout.flush()

    def finish(self):
        sys.stdout.write("\n")
        sys.stdout.flush()


class Renderer:
    # plain stdlib rendering. subclass to upgrade.
    name = "plain"

    def print_markdown(self, text):
        print(render_markdown_plain(text))

    def stream(self):
        return _PlainStream()

    def tool_call(self, name, summary=""):
        print(tool_call_line(name, summary))

    def tool_result(self, text):
        print(tool_result_line(text))

    def rule(self, width=40):
        print(brand(G["rule"] * width))

    def welcome(self, version, model, root, recent, tips):
        print(welcome_screen(version, model, root, recent, tips))


class PlainRenderer(Renderer):
    name = "plain"


class RichRenderer(Renderer):
    # markdown, syntax highlighting, and live streaming via rich.
    # only constructed when the import above succeeded.
    name = "rich"

    def __init__(self):
        self.console = _RichConsole()

    def print_markdown(self, text):
        self.console.print(_RichMarkdown(str(text)))

    def stream(self):
        return _RichStream(self.console)


class _RichStream:
    # aider-style: re-render the accumulated markdown in a live
    # region as tokens arrive. the final frame stays in the
    # scrollback when the stream stops.
    def __init__(self, console):
        self.console = console
        self.acc = ""
        self.live = _RichLive("", refresh_per_second=12,
                              console=console)
        self.live.start()

    def feed(self, token):
        self.acc += token
        self.live.update(_RichMarkdown(self.acc))

    def finish(self):
        self.live.stop()


def _plain_terminal():
    # pipes, dumb terms, and --no-color/NO_COLOR all get the
    # plain renderer. rich only when a human is watching.
    if not _enabled:
        return True
    if os.environ.get("TERM") == "dumb":
        return True
    try:
        return not sys.stdout.isatty()
    except Exception:
        return True


def get_renderer():
    # rich when it is installed and a human is watching,
    # plain stdlib everywhere else. never raises.
    if _plain_terminal():
        return PlainRenderer()
    if _RICH:
        try:
            return RichRenderer()
        except Exception:
            pass
    return PlainRenderer()


def color_diff(diff):
    # unified diff: added lines green, removed red, headers dim
    out = []
    for line in diff.splitlines(keepends=True):
        if line.startswith("+"):
            out.append(green(line))
        elif line.startswith("-"):
            out.append(red(line))
        elif line.startswith("@@"):
            out.append(dim(line))
        else:
            out.append(line)
    return "".join(out)

