"""Focus: bandwidth-limited selection of what to attend to."""


class Focus:
    """Picks the top-k candidate observations above a salience threshold."""

    def __init__(self, bandwidth=3, threshold=0.3):
        self.bandwidth = max(1, int(bandwidth))
        self.threshold = float(threshold)

    def ranked(self, candidates):
        """(name, score) pairs above threshold, best first."""
        ordered = sorted(candidates, key=lambda item: item[1], reverse=True)
        return [
            (name, score) for name, score in ordered if score >= self.threshold
        ]

    def select(self, candidates):
        """Return up to bandwidth names with score >= threshold, best first.

        Sorting is stable, so ties keep their input order.
        """
        return [name for name, _ in self.ranked(candidates)[: self.bandwidth]]

    def interrupt(self, current_best, candidate_score, margin=0.25):
        """True when a candidate captures attention from the current focus."""
        return candidate_score > current_best + margin

    def to_dict(self):
        return {"bandwidth": self.bandwidth, "threshold": self.threshold}

    @classmethod
    def from_dict(cls, data):
        return cls(
            bandwidth=data.get("bandwidth", 3),
            threshold=data.get("threshold", 0.3),
        )

contents.cognix/attention/salience.py:
"""Salience scoring: how much an observation deserves attention.

Four independent components (novelty, relevance, surprise, urgency) are
each computed by their own function, then combined with fixed weights
into a single 0..1 score.
"""

from cognix.perception.pipeline import (
    URGENCY_MARKERS,
    find_urgency_markers,
    keywords,
    mentions_date,
)

# component weights used by score_observation
WEIGHTS = {
    "novelty": 0.3,
    "relevance": 0.3,
    "surprise": 0.2,
    "urgency": 0.2,
}

_RECENT_LIMIT = 50


def _clamp01(value):
    return max(0.0, min(1.0, float(value)))


def _jaccard(first, second):
    union = first | second
    if not union:
        return 0.0
    return len(first & second) / len(union)


def _episode_text(episode):
    for attr in ("text", "content", "summary", "observation"):
        value = getattr(episode, attr, None)
        if isinstance(value, str) and value:
            return value
    if isinstance(episode, str):
        return episode
    if isinstance(episode, dict):
        for key in ("text", "content", "summary"):
            value = episode.get(key)
            if isinstance(value, str) and value:
                return value
    return str(episode)


def _recent_episodes(episodic, limit=_RECENT_LIMIT):
    if episodic is None:
        return []
    if hasattr(episodic, "recent"):
        return list(episodic.recent(limit))
    return list(episodic)[-limit:]


def _novelty_detail(text, episodic):
    words = set(keywords(text))
    if not words:
        return 0.0, "no keywords in text"
    episodes = _recent_episodes(episodic)
    if not episodes:
        return 1.0, "no prior episodes to compare against"
    best = 0.0
    for episode in episodes:
        similarity = _jaccard(words, set(keywords(_episode_text(episode))))
        if similarity > best:
            best = similarity
    return 1.0 - best, "max keyword overlap %.2f over %d episodes" % (
        best,
        len(episodes),
    )


def novelty_score(text, episodic):
    """1 minus the max keyword similarity to recent episodes (last 50)."""
    return _novelty_detail(text, episodic)[0]


def _relevance_detail(text, goals):
    words = set(keywords(text))
    if not words:
        return 0.0, "no keywords in text"
    goals = list(goals or ())
    if not goals:
        return 0.0, "no goals to compare against"
    best = 0.0
    best_goal = None
    for goal in goals:
        goal_words = set(keywords(getattr(goal, "description", "") or ""))
        if not goal_words:
            continue
        overlap = len(words & goal_words) / len(goal_words)
        if overlap > best:
            best = overlap
            best_goal = getattr(goal, "description", "")
    reason = "best goal overlap %.2f" % best
    if best_goal:
        reason += " (%s)" % best_goal[:60]
    return best, reason


def relevance_score(text, goals):
    """Keyword overlap between text and goal descriptions, best goal wins."""
    return _relevance_detail(text, goals)[0]


def _surprise_detail(text, beliefs):
    if beliefs is None:
        return 1.0, "no beliefs to compare against"
    best = 0.0
    matched = None
    seen = set()
    for word in keywords(text):
        for belief in beliefs.query(word):
            proposition = getattr(belief, "proposition", "")
            if proposition in seen:
                continue
            seen.add(proposition)
            confidence = float(getattr(belief, "confidence", 0.0))
            if confidence > best:
                best = confidence
                matched = proposition
    reason = "no matching beliefs" if matched is None else "matches %r at %.2f" % (
        matched[:60],
        best,
    )
    return 1.0 - best, reason


def surprise_score(text, beliefs):
    """1 minus the max confidence among beliefs sharing keywords with text."""
    return _surprise_detail(text, beliefs)[0]


def _urgency_detail(text):
    markers = find_urgency_markers(text)
    score = sum(URGENCY_MARKERS[marker] for marker in markers)
    dated = mentions_date(text)
    if dated:
        score += 0.25
    parts = []
    if markers:
        parts.append("markers: %s" % ", ".join(markers))
    if dated:
        parts.append("date mention")
    reason = "; ".join(parts) if parts else "no urgency markers"
    return _clamp01(score), reason


def urgency_score(text):
    """Weighted urgency markers plus date/deadline mentions, clamped 0..1."""
    return _urgency_detail(text)[0]


class SalienceSignal:
    """One named salience component with its score and a human reason."""

    def __init__(self, name, score, reason=""):
        self.name = name
        self.score = _clamp01(score)
        self.reason = reason

    def __repr__(self):
        return "SalienceSignal(%r, %.3f, %r)" % (self.name, self.score, self.reason)

    def __eq__(self, other):
        return (
            isinstance(other, SalienceSignal)
            and self.name == other.name
            and self.score == other.score
            and self.reason == other.reason
        )

    def to_dict(self):
        return {"name": self.name, "score": self.score, "reason": self.reason}

    @classmethod
    def from_dict(cls, data):
        return cls(data["name"], data["score"], data.get("reason", ""))


def score_observation(text, *, goals=(), beliefs=None, episodic=None, now=None):
    """Score an observation, returning (total, [SalienceSignal, ...]).

    Total is the weighted sum of the four components, clamped to 0..1.
    The now callable is accepted for interface consistency; scoring is
    stateless and does not use wall-clock time.
    """
    _ = now
    details = {
        "novelty": _novelty_detail(text, episodic),
        "relevance": _relevance_detail(text, goals),
        "surprise": _surprise_detail(text, beliefs),
        "urgency": _urgency_detail(text),
    }
    signals = [
        SalienceSignal(name, score, reason)
        for name, (score, reason) in details.items()
    ]
    total = sum(WEIGHTS[name] * score for name, (score, _) in details.items())
    return _clamp01(total), signals


def batch_score(texts, *, goals=(), beliefs=None, episodic=None, now=None):
    """Score many observations, returning (text, total, signals) best first."""
    scored = [
        (text, *score_observation(text, goals=goals, beliefs=beliefs,
                                 episodic=episodic, now=now))
        for text in texts
    ]
    scored.sort(key=lambda item: item[1], reverse=True)
    return scored

contents.cognix/batch.py:
"""Batch mode: run a .cx script of cognitive operations.

Script syntax, one command per line, # comments:
  observe: some text here
  goal: 0.8 do the thing
  run
  run: <goal_id>
  consolidate
  cycle: 2.0
  rehearse
  replay
  recall: query text
  curiosity: some text here      # novelty score, or boredom state when empty
  expand                         # expand the last goal into subgoals
  expand: <goal_id>
  runall                         # run every active goal in priority order
  assert: belief <substring>        # a belief mentioning substring must exist
  assert: goal-done <goal_id>       # goal must have status done
  assert: note <name> <substring>    # note must contain substring
  save: path.json
  print: some literal text
"""

import shlex


BARE_COMMANDS = {"run", "consolidate", "rehearse", "cycle", "replay",
                 "expand", "runall", "curiosity"}


def parse_line(line):
    line = line.strip()
    if not line or line.startswith("#"):
        return None
    lowered = line.lower()
    if lowered in BARE_COMMANDS:
        return (lowered, "")
    if ":" not in line:
        return ("observe", line)
    kind, rest = line.split(":", 1)
    return (kind.strip().lower(), rest.strip())


def run_batch_file(runtime, path):
    with open(path, "r", encoding="utf-8") as fh:
        lines = fh.readlines()
    return run_batch(runtime, lines)


def run_batch(runtime, lines):
    results = []
    last_goal_id = None
    for lineno, raw in enumerate(lines, 1):
        parsed = parse_line(raw)
        if parsed is None:
            continue
        kind, rest = parsed
        label = "line %d (%s)" % (lineno, kind)
        try:
            if kind == "observe":
                report = runtime.observe(rest)
                results.append((label, True, "salience=%.2f" % report.get("salience", 0)))
            elif kind == "goal":
                priority, _, text = rest.partition(" ")
                try:
                    priority = float(priority)
                except ValueError:
                    text, priority = rest, 0.5
                goal = runtime.add_goal(text.strip(), priority=priority)
                last_goal_id = goal.id
                results.append((label, True, "goal %s" % goal.id))
            elif kind == "run":
                result = runtime.run_goal(rest or last_goal_id)
                results.append((label, bool(result.get("ok")),
                                result.get("summary") or result.get("error", "")))
            elif kind == "consolidate":
                stats = runtime.consolidate()
                results.append((label, True, str(stats)))
            elif kind == "cycle":
                runtime.cycle(float(rest or 1.0))
                results.append((label, True, "ticked"))
            elif kind == "rehearse":
                for item in runtime.working.top(20):
                    runtime.working.rehearse(item.id)
                results.append((label, True, "rehearsed"))
            elif kind == "replay":
                stats = runtime.consolidate()["replay"]
                results.append((label, True, "replayed=%d" % stats["replayed"]))
            elif kind == "curiosity":
                if rest:
                    score = runtime.curiosity.novelty(rest)
                    results.append((label, True, "novelty=%.2f" % score))
                else:
                    results.append((label, True, "boredom=%.2f" % runtime.curiosity.boredom()))
            elif kind == "expand":
                target = rest or last_goal_id
                children = runtime.expand_goal(target) if target else []
                results.append((label, True, "%d subgoals" % len(children)))
            elif kind == "runall":
                done = runtime.run_all_goals()
                ok = all(r.get("ok") for r in done)
                results.append((label, ok, "%d goals run" % len(done)))
            elif kind == "recall":
                hits = runtime.recall(rest, k=5)
                results.append((label, True, "%d hits" % len(hits)))
            elif kind == "save":
                path = runtime.save(rest)
                results.append((label, True, path))
            elif kind == "print":
                print(rest)
                results.append((label, True, "printed"))
            elif kind == "assert":
                ok, detail = run_assert(runtime, rest, last_goal_id)
                results.append((label, ok, detail))
            else:
                results.append((label, False, "unknown command %r" % kind))
        except Exception as exc:
            results.append((label, False, "raised: %s" % exc))
    return results


def run_assert(runtime, rest, last_goal_id):
    parts = shlex.split(rest)
    if not parts:
        return False, "empty assert"
    kind = parts[0]
    if kind == "belief":
        needle = " ".join(parts[1:]).lower()
        found = [b for b in runtime.beliefs.strongest(200)
                 if needle in b.proposition.lower()]
        return (len(found) > 0, "%d matching beliefs" % len(found))
    if kind == "goal-done":
        goal_id = parts[1] if len(parts) > 1 else last_goal_id
        goal = runtime.goals.get(goal_id) if goal_id else None
        ok = goal is not None and goal.status == "done"
        return ok, "status=%s" % (goal.status if goal else "missing")
    if kind == "note":
        name = parts[1] if len(parts) > 1 else ""
        needle = " ".join(parts[2:]) if len(parts) > 2 else ""
        result = runtime.tools.call("note_read", {"name": name})
        ok = result.get("ok") and needle in str(result.get("result", ""))
        return ok, "note check"
    if kind == "episodes":
        minimum = int(parts[1]) if len(parts) > 1 else 1
        count = runtime.episodic.count()
        return count >= minimum, "episodes=%d" % count
    return False, "unknown assert kind %r" % kind

contents.cognix/config.py:
"""Layered configuration for cognix: defaults, files, env vars, overrides."""

import json
import os

DEFAULTS = {
    "memory": {
        "working_capacity": 7,
        "decay_rate": 0.08,
        "activation_threshold": 0.05,
        "consolidation_threshold": 0.6,
        "min_rehearsals": 2,
        "semantic_support": 3,
        "episodic_max_age_days": 30,
        "replay_budget": 5,
        "replay_min_salience": 0.4,
    },
    "attention": {
        "bandwidth": 3,
        "salience_threshold": 0.3,
        "arousal_baseline": 0.5,
        "curiosity_bonus_scale": 0.15,
        "curiosity_boredom_threshold": 0.8,
    },
    "agent": {
        "max_retries": 2,
        "step_timeout": 30.0,
        "default_strategy": "auto",
        "max_attempts": 3,
    },
    "tools": {
        "workspace_dir": ".",
        "shell_enabled": True,
        "plugin_dir": "plugins",
    },
    "runtime": {
        "autosave": False,
        "save_path": "cognix_state.json",
        "consolidate_every": 10,
    },
}


def _deep_copy(value):
    if isinstance(value, dict):
        return {k: _deep_copy(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_deep_copy(v) for v in value]
    return value


def _deep_merge(base, overrides):
    out = _deep_copy(base)
    for key, value in overrides.items():
        if isinstance(value, dict) and isinstance(out.get(key), dict):
            out[key] = _deep_merge(out[key], value)
        else:
            out[key] = _deep_copy(value)
    return out


def _coerce(value, example):
    # coerce a string from env into the type of the default
    if isinstance(example, bool):
        return value.strip().lower() in ("1", "true", "yes", "on")
    if isinstance(example, int):
        return int(float(value))
    if isinstance(example, float):
        return float(value)
    return value


class Config:
    """Nested config with dotted-path access."""

    def __init__(self, data=None):
        self.data = _deep_copy(DEFAULTS)
        if data:
            self.data = _deep_merge(self.data, data)

    @classmethod
    def defaults(cls):
        return cls()

    @classmethod
    def load(cls, path):
        with open(path, "r", encoding="utf-8") as fh:
            return cls(json.load(fh))

    @classmethod
    def from_env(cls, prefix="COGNIX_"):
        # COGNIX_MEMORY__WORKING_CAPACITY=9 style overrides
        cfg = cls()
        for env_key, env_val in os.environ.items():
            if not env_key.startswith(prefix):
                continue
            path = env_key[len(prefix):].lower().split("__")
            node = cfg.data
            example = None
            ok = True
            for part in path[:-1]:
                node = node.get(part)
                if not isinstance(node, dict):
                    ok = False
                    break
            if not ok:
                continue
            leaf = path[-1]
            if leaf not in node:
                continue
            node[leaf] = _coerce(env_val, node[leaf])
        return cfg

    def get(self, dotted, default=None):
        node = self.data
        for part in dotted.split("."):
            if not isinstance(node, dict) or part not in node:
                return default
            node = node[part]
        return node

    def set(self, dotted, value):
        parts = dotted.split(".")
        node = self.data
        for part in parts[:-1]:
            node = node.setdefault(part, {})
        node[parts[-1]] = value

    def merge(self, overrides):
        return Config(_deep_merge(self.data, overrides))

    def validate(self):
        # returns a list of human-readable problems, empty means fine
        problems = []
        checks = [
            ("memory.working_capacity", int, 1, 100),
            ("memory.decay_rate", float, 0.0, 1.0),
            ("memory.activation_threshold", float, 0.0, 1.0),
            ("memory.consolidation_threshold", float, 0.0, 1.0),
            ("memory.min_rehearsals", int, 0, 100),
            ("memory.semantic_support", int, 1, 1000),
            ("memory.replay_budget", int, 1, 100),
            ("memory.replay_min_salience", float, 0.0, 1.0),
            ("attention.bandwidth", int, 1, 20),
            ("attention.salience_threshold", float, 0.0, 1.0),
            ("attention.curiosity_bonus_scale", float, 0.0, 1.0),
            ("attention.curiosity_boredom_threshold", float, 0.0, 1.0),
            ("agent.max_retries", int, 0, 10),
            ("agent.step_timeout", float, 0.1, 3600.0),
            ("agent.max_attempts", int, 1, 10),
            ("runtime.consolidate_every", int, 1, 10000),
        ]
        for dotted, kind, lo, hi in checks:
            value = self.get(dotted)
            if not isinstance(value, kind) or isinstance(value, bool):
                problems.append("%s should be %s, got %r" % (dotted, kind.__name__, value))
            elif not (lo <= value <= hi):
                problems.append("%s out of range [%s, %s]: %r" % (dotted, lo, hi, value))
        if self.get("agent.default_strategy") not in ("auto", "decompose", "reactive", "means_ends"):
            problems.append("agent.default_strategy is not a known strategy")
        return problems

    def save(self, path):
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(self.data, fh, indent=2)

    def to_dict(self):
        return _deep_copy(self.data)

    @classmethod
    def from_dict(cls, data):
        return cls(data)

