"""Attach to a process and read/write its memory.

linux goes through /proc/<pid>/mem with pread/pwrite.
windows uses ReadProcessMemory/WriteProcessMemory via ctypes.
macos raises UnsupportedPlatformError.
"""
import os
import struct
import sys

from memkit.types import POINTER_FMT, POINTER_SIZE, pack, unpack


class UnsupportedPlatformError(RuntimeError):
    pass


def platform_name():
    if sys.platform.startswith("win"):
        return "windows"
    if sys.platform.startswith("linux"):
        return "linux"
    if sys.platform.startswith("darwin"):
        return "macos"
    return "unknown"


def find_processes(name):
    # returns [(pid, label)] where the name matches, case-insensitive
    plat = platform_name()
    if plat == "linux":
        return _find_processes_linux(name)
    if plat == "windows":
        return _find_processes_windows(name)
    raise UnsupportedPlatformError("process search is not supported here")


def _find_processes_linux(name):
    needle = name.lower()
    found = []
    for entry in os.listdir("/proc"):
        if not entry.isdigit():
            continue
        pid = int(entry)
        try:
            with open("/proc/%d/comm" % pid) as f:
                comm = f.read().strip()
            with open("/proc/%d/cmdline" % pid, "rb") as f:
                cmd = f.read().replace(b"\x00", b" ").decode(errors="replace").strip()
        except OSError:
            continue
        label = cmd or comm
        if needle in comm.lower() or needle in label.lower():
            found.append((pid, comm))
    return found


def _find_processes_windows(name):
    import ctypes
    from ctypes import wintypes

    needle = name.lower()
    TH32CS_SNAPPROCESS = 0x2

    class PROCESSENTRY32(ctypes.Structure):
        _fields_ = [
            ("dwSize", wintypes.DWORD),
            ("cntUsage", wintypes.DWORD),
            ("th32ProcessID", wintypes.DWORD),
            ("th32DefaultHeapID", ctypes.c_ulonglong),
            ("th32ModuleID", wintypes.DWORD),
            ("cntThreads", wintypes.DWORD),
            ("th32ParentProcessID", wintypes.DWORD),
            ("pcPriClassBase", wintypes.LONG),
            ("dwFlags", wintypes.DWORD),
            ("szExeFile", wintypes.CHAR * 260),
        ]

    k32 = ctypes.windll.kernel32
    snap = k32.CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0)
    if snap == wintypes.HANDLE(-1).value:
        raise OSError("CreateToolhelp32Snapshot failed")
    found = []
    try:
        entry = PROCESSENTRY32()
        entry.dwSize = ctypes.sizeof(entry)
        ok = k32.Process32First(snap, ctypes.byref(entry))
        while ok:
            exe = entry.szExeFile.decode(errors="replace")
            if needle in exe.lower():
                found.append((entry.th32ProcessID, exe))
            ok = k32.Process32Next(snap, ctypes.byref(entry))
    finally:
        k32.CloseHandle(snap)
    return found


class Process:
    """Open handle to a target process for memory access."""

    def __init__(self, pid):
        self.pid = int(pid)
        self._plat = platform_name()
        if self._plat == "macos":
            raise UnsupportedPlatformError("macos is not supported by memkit")
        if self._plat == "unknown":
            raise UnsupportedPlatformError("unsupported platform: %s" % sys.platform)
        if self._plat == "linux":
            self._open_linux()
        else:
            self._open_windows()

    @classmethod
    def attach_pid(cls, pid):
        return cls(pid)

    @classmethod
    def attach_name(cls, name):
        matches = find_processes(name)
        if not matches:
            raise ProcessLookupError("no process matching %r" % name)
        if len(matches) > 1:
            descs = ", ".join("%d (%s)" % (pid, label) for pid, label in matches)
            raise ProcessLookupError("multiple processes match: %s" % descs)
        return cls(matches[0][0])

    # linux backend
    def _open_linux(self):
        self._fd = os.open("/proc/%d/mem" % self.pid, os.O_RDWR)

    def _read_linux(self, address, size):
        return os.pread(self._fd, size, address)

    def _write_linux(self, address, data):
        written = 0
        view = memoryview(data)
        while written < len(view):
            n = os.pwrite(self._fd, view[written:], address + written)
            if n == 0:
                raise OSError("short write at %#x" % address)
            written += n

    def _close_linux(self):
        os.close(self._fd)

    # windows backend
    def _open_windows(self):
        import ctypes
        from ctypes import wintypes

        k32 = ctypes.windll.kernel32
        k32.OpenProcess.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]
        k32.OpenProcess.restype = wintypes.HANDLE
        access = 0x0010 | 0x0020 | 0x0008 | 0x0400  # vm read/write/operation + query
        handle = k32.OpenProcess(access, False, self.pid)
        if not handle:
            raise OSError("OpenProcess failed for pid %d" % self.pid)
        self._k32 = k32
        self._handle = handle

    def _read_windows(self, address, size):
        import ctypes

        buf = ctypes.create_string_buffer(size)
        got = ctypes.c_size_t(0)
        ok = self._k32.ReadProcessMemory(
            self._handle, ctypes.c_void_p(address), buf, size, ctypes.byref(got)
        )
        if not ok:
            raise OSError("ReadProcessMemory failed at %#x" % address)
        return buf.raw[: got.value]

    def _write_windows(self, address, data):
        import ctypes

        got = ctypes.c_size_t(0)
        ok = self._k32.WriteProcessMemory(
            self._handle, ctypes.c_void_p(address), bytes(data), len(data), ctypes.byref(got)
        )
        if not ok or got.value != len(data):
            raise OSError("WriteProcessMemory failed at %#x" % address)

    def _close_windows(self):
        self._k32.CloseHandle(self._handle)

    # public api
    def read(self, address, size):
        if address < 0 or size < 0:
            raise ValueError("address and size must be non-negative")
        if size == 0:
            return b""
        if self._plat == "linux":
            return self._read_linux(address, size)
        return self._read_windows(address, size)

    def write(self, address, data):
        data = bytes(data)
        if not data:
            return
        if self._plat == "linux":
            self._write_linux(address, data)
        else:
            self._write_windows(address, data)

    def read_value(self, type_name, address):
        from memkit.types import check_type

        _, size = check_type(type_name)
        return unpack(type_name, self.read(address, size))

    def write_value(self, type_name, address, value):
        self.write(address, pack(type_name, value))

    def read_pointer(self, address):
        return struct.unpack(POINTER_FMT, self.read(address, POINTER_SIZE))[0]

    def read_string(self, address, max_length=256):
        data = self.read(address, max_length)
        return data.split(b"\x00", 1)[0].decode(errors="replace")

    def write_string(self, address, text):
        self.write(address, text.encode() + b"\x00")

    def close(self):
        if self._plat == "linux":
            self._close_linux()
        else:
            self._close_windows()

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()

contents.memkit/ptrscan.py:
"""Automatic pointer scanner.

Given a target address, find pointer chains leading to it: scan memory
for slots holding values near the target, then recurse outward to a
configurable depth. Chains are deduplicated and ranked by depth, so the
most useful (deepest, smallest offset) chains come first.
"""
import struct
from bisect import bisect_left, bisect_right

from memkit.regions import list_regions
from memkit.types import POINTER_FMT, POINTER_SIZE

CHUNK_SIZE = 1 << 16


class Chain:
    """One pointer chain, outermost slot first.

    steps is a list of (address, offset) where reading the pointer at
    address and adding offset gives the next address in the chain, and
    the last step lands on the scan target.
    """

    def __init__(self, steps):
        self.steps = list(steps)

    @property
    def depth(self):
        return len(self.steps)

    @property
    def base_address(self):
        return self.steps[0][0] if self.steps else None

    @property
    def total_offset(self):
        return sum(off for _, off in self.steps)

    @property
    def addresses(self):
        return [addr for addr, _ in self.steps]

    def resolve(self, process):
        """Walk the chain in the target process, return the final address.

        Each step reads the pointer at the running address and adds its
        offset; the result feeds the next step, so every hop in the
        chain actually matters.
        """
        addr = None
        for address, offset in self.steps:
            if addr is None:
                addr = address
            addr = process.read_pointer(addr) + offset
        return addr

    def describe(self, target=None):
        parts = []
        for address, offset in self.steps:
            parts.append("%#x + %#x" % (address, offset))
        if target is not None:
            parts.append("-> %#x" % target)
        return " ".join(parts)

    def __repr__(self):

        return "Chain(depth=%d, base=%#x)" % (self.depth,
                                              self.base_address or 0)

    def __eq__(self, other):
        return isinstance(other, Chain) and self.steps == other.steps

    def __hash__(self):
        return hash(tuple(self.steps))


def _mapped_ranges(pid):
    # sorted (start, end) of every mapped region for the mapped check
    ranges = [(r.start, r.end) for r in list_regions(pid)]
    ranges.sort()
    return ranges


def _is_mapped(ranges, value):
    # binary search for a range containing value
    starts = [s for s, _ in ranges]
    i = bisect_right(starts, value) - 1
    return i >= 0 and ranges[i][0] <= value < ranges[i][1]


def _iter_pointer_slots(process, ranges, start, end, writable_only):
    # yield (slot_address, value) for each aligned pointer-sized slot
    for region in list_regions(process.pid):
        if not region.readable:
            continue
        if writable_only and not region.writable:
            continue
        lo = max(region.start, start or 0)
        hi = min(region.end, end if end else region.end)
        if hi <= lo:
            continue
        addr = lo + (-lo % POINTER_SIZE)
        while addr < hi:
            n = min(CHUNK_SIZE, hi - addr)
            try:
                data = process.read(addr, n)
            except OSError:
                addr += n
                continue
            for i in range(0, len(data) - POINTER_SIZE + 1, POINTER_SIZE):
                (value,) = struct.unpack_from(POINTER_FMT, data, i)
                yield addr + i, value
            addr += n


def scan_pointers(process, target, max_offset=0x1000, depth=3, start=None,
                  end=None, writable_only=True, require_mapped=True,
                  max_results=10000):
    """Find pointer chains leading to target.

    A slot holding value v links to target when target - max_offset <= v
    <= target, with offset target - v. Each level outward repeats the
    search using the previous level's slots as new targets. Returns
    chains ranked deepest first, then by smallest total offset.
    """
    if max_offset < 0:
        raise ValueError("max_offset must be non-negative")
    if depth < 1:
        raise ValueError("depth must be at least 1")
    ranges = _mapped_ranges(process.pid) if require_mapped else []
    found = []
    # current maps each target address to the chains that end there
    current = {int(target): [Chain([])]}
    for _ in range(depth):
        # sorted targets let each slot binary-search the targets it can
        # reach instead of checking every target for every slot
        targets = sorted(current.items())
        taddrs = [t for t, _ in targets]
        next_targets = {}
        for slot, value in _iter_pointer_slots(process, ranges, start, end,
                                               writable_only):
            if require_mapped and not _is_mapped(ranges, value):
                continue
            lo = bisect_left(taddrs, value)
            hi = bisect_right(taddrs, value + max_offset)
            for taddr, suffixes in targets[lo:hi]:
                offset = taddr - value
                for suffix in suffixes:
                    if slot in suffix.addresses:
                        continue  # would be a cycle
                    chain = Chain([(slot, offset)] + suffix.steps)
                    found.append(chain)
                    next_targets.setdefault(slot, []).append(chain)
                    if len(found) >= max_results:
                        break
                if len(found) >= max_results:
                    break
            if len(found) >= max_results:
                break
        if not next_targets:
            break
        current = next_targets
    found.sort(key=lambda c: (-c.depth, c.total_offset))
    return found[:max_results]

contents.memkit/regions.py:
"""List readable memory regions of a target process.

linux parses /proc/<pid>/maps.
windows walks VirtualQueryEx.
"""
from memkit.process import UnsupportedPlatformError, platform_name


class Region:
    def __init__(self, start, end, perms, name=""):
        self.start = start
        self.end = end
        self.perms = perms
        self.name = name

    @property
    def size(self):
        return self.end - self.start

    @property
    def readable(self):
        return "r" in self.perms

    @property
    def writable(self):
        return "w" in self.perms

    @property
    def executable(self):
        return "x" in self.perms

    def contains(self, address):
        return self.start <= address < self.end

    def __repr__(self):
        return "Region(%#x-%#x %s %s)" % (self.start, self.end, self.perms, self.name)


def list_regions(pid):
    plat = platform_name()
    if plat == "linux":
        return _linux_regions(pid)
    if plat == "windows":
        return _windows_regions(pid)
    raise UnsupportedPlatformError("region listing is not supported here")


def _linux_regions(pid):
    regions = []
    with open("/proc/%d/maps" % pid) as f:
        for line in f:
            parts = line.split()
            if len(parts) < 2:
                continue
            span, perms = parts[0], parts[1]
            try:
                start_s, end_s = span.split("-", 1)
                start, end = int(start_s, 16), int(end_s, 16)
            except ValueError:
                continue
            name = parts[5] if len(parts) > 5 else ""
            regions.append(Region(start, end, perms, name))
    return regions


def _protect_to_perms(protect):
    # windows page protection constants to an rwx string
    PAGE_NOACCESS = 0x01
    PAGE_READONLY = 0x02
    PAGE_READWRITE = 0x04
    PAGE_WRITECOPY = 0x08
    PAGE_EXECUTE = 0x10
    PAGE_EXECUTE_READ = 0x20
    PAGE_EXECUTE_READWRITE = 0x40
    PAGE_EXECUTE_WRITECOPY = 0x80
    PAGE_GUARD = 0x100
    if protect & PAGE_GUARD or protect & PAGE_NOACCESS:
        return "---"
    perms = ""
    perms += "r" if protect & (PAGE_READONLY | PAGE_READWRITE | PAGE_WRITECOPY |
                               PAGE_EXECUTE_READ | PAGE_EXECUTE_READWRITE |
                               PAGE_EXECUTE_WRITECOPY) else "-"
    perms += "w" if protect & (PAGE_READWRITE | PAGE_WRITECOPY |
                               PAGE_EXECUTE_READWRITE | PAGE_EXECUTE_WRITECOPY) else "-"
    perms += "x" if protect & (PAGE_EXECUTE | PAGE_EXECUTE_READ |
                               PAGE_EXECUTE_READWRITE | PAGE_EXECUTE_WRITECOPY) else "-"
    return perms


def _windows_regions(pid):
    import ctypes
    from ctypes import wintypes

    k32 = ctypes.windll.kernel32
    access = 0x0400  # query information only, no read needed
    handle = k32.OpenProcess(access, False, pid)
    if not handle:
        raise OSError("OpenProcess failed for pid %d" % pid)

    class MEMORY_BASIC_INFORMATION(ctypes.Structure):
        _fields_ = [
            ("BaseAddress", ctypes.c_void_p),
            ("AllocationBase", ctypes.c_void_p),
            ("AllocationProtect", wintypes.DWORD),
            ("RegionSize", ctypes.c_size_t),
            ("State", wintypes.DWORD),
            ("Protect", wintypes.DWORD),
            ("Type", wintypes.DWORD),
        ]

    MEM_COMMIT = 0x1000
    regions = []
    try:
        addr = 0
        mbi = MEMORY_BASIC_INFORMATION()
        while True:
            ret = k32.VirtualQueryEx(
                handle, ctypes.c_void_p(addr), ctypes.byref(mbi), ctypes.sizeof(mbi)
            )
            if not ret:
                break
            if mbi.State == MEM_COMMIT:
                base = mbi.BaseAddress
                regions.append(
                    Region(base, base + mbi.RegionSize, _protect_to_perms(mbi.Protect))
                )
            addr = mbi.BaseAddress + mbi.RegionSize
            if addr >= (1 << 47):
                break
    finally:
        k32.CloseHandle(handle)
    return regions

contents.memkit/scan.py:
"""Multi-pass value scanner, cheat-engine style.

First pass walks readable regions in chunks and records candidate addresses.
Later passes only re-read the candidates, so narrowing is fast.
"""
from memkit.regions import list_regions
from memkit.types import check_type, pack, unpack

CHUNK_SIZE = 1 << 16


class Scanner:
    def __init__(self, process, type_name="u32"):
        check_type(type_name)
        self.process = process
        self.type_name = type_name
        _, self.size = check_type(type_name)
        self.candidates = []
        self._snapshot = {}
        self._primed = False

    def _spans(self, start, end):
        spans = []
        for region in list_regions(self.process.pid):
            if not region.readable:
                continue
            lo = max(region.start, start or 0)
            hi = min(region.end, end if end else region.end)
            if hi > lo:
                spans.append((lo, hi))
        return spans

    def _iter_slots(self, start, end):
        # yield (address, raw bytes) for each aligned slot in the spans
        for lo, hi in self._spans(start, end):
            addr = lo
            while addr < hi:
                n = min(CHUNK_SIZE, hi - addr)
                try:
                    data = self.process.read(addr, n)
                except OSError:
                    addr += n
                    continue
                off = (-addr) % self.size
                stop = len(data) - self.size + 1
                for i in range(off, stop, self.size):
                    yield addr + i, data[i : i + self.size]
                addr += n

    def scan_exact(self, value, start=None, end=None):
        """First pass finds every match. Later passes keep still-matching ones."""
        needle = pack(self.type_name, value)
        if not self._primed:
            self.candidates = []
            self._snapshot = {}
            for addr, raw in self._iter_slots(start, end):
                if raw == needle:
                    self.candidates.append(addr)
                    self._snapshot[addr] = raw
            self._primed = True
        else:
            alive = {}
            for addr in self.candidates:
                try:
                    alive[addr] = self.process.read(addr, self.size)
                except OSError:
                    continue
            self.candidates = [a for a in alive if alive[a] == needle]
            self._snapshot = alive
        return self.candidates

    def scan_initial(self, start=None, end=None):
        """Snapshot every value in range, for changed/unchanged style scans."""
        self.candidates = []
        self._snapshot = {}
        for addr, raw in self._iter_slots(start, end):
            self.candidates.append(addr)
            self._snapshot[addr] = raw
        self._primed = True
        return self.candidates

    def _narrow(self, predicate):
        if not self._primed:
            raise RuntimeError("run scan_exact or scan_initial first")
        old = self._snapshot
        alive = {}
        for addr in self.candidates:
            try:
                alive[addr] = self.process.read(addr, self.size)
            except OSError:
                continue
        self.candidates = [a for a in alive if predicate(old[a], alive[a])]
        self._snapshot = alive
        return self.candidates

    def scan_changed(self):
        return self._narrow(lambda o, n: o != n)

    def scan_unchanged(self):
        return self._narrow(lambda o, n: o == n)

    def scan_increased(self):
        return self._narrow(
            lambda o, n: unpack(self.type_name, n) > unpack(self.type_name, o)
        )

    def scan_decreased(self):
        return self._narrow(
            lambda o, n: unpack(self.type_name, n) < unpack(self.type_name, o)
        )

    def clear(self):
        self.candidates = []
        self._snapshot = {}

    def __len__(self):
        return len(self.candidates)

contents.memkit/scripting.py:
"""Scripting: run user python against a target through a convenience api.

Scripts are plain python files. They get one global, ``target``, a
ScriptTarget wrapping the attached process. This is not a sandbox:
scripts run with your full python and your privileges, so only run
scripts you trust, the same deal as cheat engine lua scripts.

Example script:

    hits = target.scan("u32", 100)
    for address in hits:
        target.write("u32", address, 999)
    print("patched", len(hits), "addresses")
"""
import os


class ScriptTarget:
    """The only object a script touches. It wraps a Process and exposes
    a curated set of operations: typed reads and writes, scans, string
    search, regions and snapshots."""

    def __init__(self, process):
        self._process = process

    @property
    def pid(self):
        return self._process.pid

    # reads and writes
    def read(self, type_name, address):
        return self._process.read_value(type_name, address)

    def write(self, type_name, address, value):
        self._process.write_value(type_name, address, value)

    def read_bytes(self, address, size):
        return self._process.read(address, size)

    def write_bytes(self, address, data):
        self._process.write(address, data)

    def read_pointer(self, address):
        return self._process.read_pointer(address)

    def read_string(self, address, max_length=256):
        return self._process.read_string(address, max_length)

    # regions
    def regions(self):
        from memkit.regions import list_regions
        return list_regions(self._process.pid)

    # scans
    def scan(self, type_name, value, start=None, end=None):
        """Exact value scan, returns a list of matching addresses."""
        from memkit.scan import Scanner
        scanner = Scanner(self._process, type_name)
        return list(scanner.scan_exact(value, start, end))

    def scan_aob(self, pattern, start=None, end=None):
        from memkit.aob import scan_pattern
        return list(scan_pattern(self._process, pattern, start, end))

    def find_strings(self, min_length=4, start=None, end=None):
        from memkit.strings import scan_strings
        return scan_strings(self._process, min_length,
                            start=start, end=end)

    def snapshot(self, addresses, type_name):
        from memkit.session import take_snapshot
        return take_snapshot(self._process, addresses, type_name)

    def __repr__(self):
        return "ScriptTarget(pid=%r)" % (self.pid,)


def run_script(source, process, script_name="<script>"):
    """Compile and run script source with ``target`` bound to a
    ScriptTarget for process. Returns the script's globals dict."""
    target = ScriptTarget(process)
    namespace = {
        "target": target,
        "__name__": "__memkit_script__",
        "__script__": script_name,
    }
    code = compile(source, script_name, "exec")
    exec(code, namespace)
    return namespace


def run_script_file(path, process):
    """Read a .py file and run it against process."""
    if not os.path.isfile(path):
        raise FileNotFoundError("no script at %r" % path)
    with open(path, "r", encoding="utf-8") as f:
        source = f.read()
    return run_script(source, process, script_name=path)

contents.memkit/session.py:
"""Scan sessions and memory snapshots.

A Session collects labeled scan results and snapshots in memory and
saves them as JSON so a hunt can continue later. Snapshots record the
values at a set of addresses; diffing two snapshots shows what changed.
"""
import json
import os
from datetime import datetime, timezone

FORMAT = "memkit-session/1"


def _utcnow():
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def _encode_value(value):
    if isinstance(value, bytes):
        return {"__bytes__": value.hex()}
    return value


def _decode_value(value):
    if isinstance(value, dict) and "__bytes__" in value:
        return bytes.fromhex(value["__bytes__"])
    return value


def _norm_result(result):
    # accept (address, value) tuples or {"address":.., "value":..} dicts
    if isinstance(result, dict):
        return (result["address"], result["value"])
    address, value = result
    return (address, value)


class ScanRecord:
    """One labeled scan: addresses matched for a value type."""
    def __init__(self, label, value_type, results, time=None):
        self.label = label
        self.value_type = value_type
        self.results = [_norm_result(r) for r in results]
        self.time = time or _utcnow()

    @property
    def addresses(self):
        return [address for address, _ in self.results]

    def to_dict(self):
        return {
            "label": self.label,
            "value_type": self.value_type,
            "time": self.time,
            "results": [[a, _encode_value(v)] for a, v in self.results],
        }

    @classmethod
    def from_dict(cls, data):
        return cls(
            data["label"],
            data["value_type"],
            [(a, _decode_value(v)) for a, v in data["results"]],
            data.get("time"),
        )

    def __len__(self):
        return len(self.results)

    def __eq__(self, other):
        return (isinstance(other, ScanRecord)
                and self.label == other.label
                and self.value_type == other.value_type
                and self.results == other.results)

    def __repr__(self):
        return "ScanRecord(%r, %r, %d results)" % (self.label,
                                                   self.value_type,
                                                   len(self.results))


class Snapshot:
    """Values read at a set of addresses at one point in time."""
    def __init__(self, value_type, values, errors=None, time=None):
        self.value_type = value_type
        self.values = dict(values)
        self.errors = dict(errors or {})
        self.time = time or _utcnow()

    def diff(self, other):
        """Compare an older snapshot (self) to a newer one (other).

        Returns a dict with changed (address, old, new) triples,
        added and removed address lists, and addresses that failed
        to read in either snapshot."""
        if self.value_type != other.value_type:
            raise ValueError("cannot diff %r against %r snapshots"
                             % (self.value_type, other.value_type))
        changed, added, removed = [], [], []
        for address, new_value in other.values.items():
            if address in self.values:
                if self.values[address] != new_value:
                    changed.append((address, self.values[address], new_value))
            else:
                added.append(address)
        for address in self.values:
            if address not in other.values:
                removed.append(address)
        unreadable = sorted(set(self.errors) | set(other.errors))
        return {
            "changed": sorted(changed),
            "added": sorted(added),
            "removed": sorted(removed),
            "unreadable": unreadable,
        }

    def to_dict(self):
        return {
            "value_type": self.value_type,
            "time": self.time,
            "values": [[a, _encode_value(v)] for a, v in self.values.items()],
            "errors": [[a, e] for a, e in self.errors.items()],
        }

    @classmethod
    def from_dict(cls, data):
        return cls(
            data["value_type"],
            {a: _decode_value(v) for a, v in data["values"]},
            {a: e for a, e in data.get("errors", [])},
            data.get("time"),
        )

    def __len__(self):
        return len(self.values)

    def __eq__(self, other):
        return (isinstance(other, Snapshot)
                and self.value_type == other.value_type
                and self.values == other.values
                and self.errors == other.errors)


def take_snapshot(process, addresses, value_type):
    """Read value_type at each address. Unreadable addresses land in
    the snapshot's errors instead of aborting the whole snapshot."""
    values, errors = {}, {}
    for address in addresses:
        try:
            values[address] = process.read_value(value_type, address)
        except (OSError, ValueError) as e:
            errors[address] = str(e)
    return Snapshot(value_type, values, errors)


class Session:
    """A named collection of scan records and snapshots on disk as JSON."""
    def __init__(self, name="session"):
        self.name = name
        self.created = _utcnow()
        self.scans = []
        self.snapshots = []  # list of (label, Snapshot)

    def add_scan(self, label, value_type, results):
        record = ScanRecord(label, value_type, results)
        self.scans.append(record)
        return record

    def add_snapshot(self, label, snapshot):
        if not isinstance(snapshot, Snapshot):
            raise ValueError("expected a Snapshot")
        self.snapshots.append((label, snapshot))
        return snapshot

    def labels(self):
        return [record.label for record in self.scans]

    def get_scans(self, label):
        return [r for r in self.scans if r.label == label]

    def latest(self, label):
        matches = self.get_scans(label)
        if not matches:
            raise KeyError("no scan labeled %r" % label)
        return matches[-1]

    def get_snapshot(self, label):
        for snap_label, snapshot in self.snapshots:
            if snap_label == label:
                return snapshot
        raise KeyError("no snapshot labeled %r" % label)

    def to_dict(self):
        return {
            "format": FORMAT,
            "name": self.name,
            "created": self.created,
            "scans": [r.to_dict() for r in self.scans],
            "snapshots": [[label, snap.to_dict()]
                          for label, snap in self.snapshots],
        }

    def save(self, path):
        directory = os.path.dirname(os.path.abspath(path))
        os.makedirs(directory, exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(self.to_dict(), f, indent=2)

    @classmethod
    def load(cls, path):
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if data.get("format") != FORMAT:
            raise ValueError("%r is not a memkit session file" % path)
        session = cls(data.get("name", "session"))
        session.created = data.get("created", session.created)
        session.scans = [ScanRecord.from_dict(r) for r in data["scans"]]
        session.snapshots = [(label, Snapshot.from_dict(s))
                             for label, s in data["snapshots"]]
        return session

    def __len__(self):
        return len(self.scans)

    def __repr__(self):
        return "Session(%r, %d scans, %d snapshots)" % (self.name,
                                                        len(self.scans),
                                                        len(self.snapshots))

