contents.src/chip8/cpu.py:
"""CPU core for the CHIP-8 emulator.

Memory map: 4K total. Fontset lives at 0x050-0x0A0, programs load at 0x200.
Classic shift quirk: 8XY6/8XYE shift Vx directly, ignoring Vy.
FX55/FX65 leave I unchanged (the modern behavior).
"""

import random

MEM_SIZE = 4096
DISPLAY_W = 64
DISPLAY_H = 32
STACK_DEPTH = 16
ROM_START = 0x200
FONT_START = 0x050

# the classic hex fontset, 5 bytes per glyph, 0-F
FONTSET = [
    0xF0, 0x90, 0x90, 0x90, 0xF0,  # 0
    0x20, 0x60, 0x20, 0x20, 0x70,  # 1
    0xF0, 0x10, 0xF0, 0x80, 0xF0,  # 2
    0xF0, 0x10, 0xF0, 0x10, 0xF0,  # 3
    0x90, 0x90, 0xF0, 0x10, 0x10,  # 4
    0xF0, 0x80, 0xF0, 0x10, 0xF0,  # 5
    0xF0, 0x80, 0xF0, 0x90, 0xF0,  # 6
    0xF0, 0x10, 0x20, 0x40, 0x40,  # 7
    0xF0, 0x90, 0xF0, 0x90, 0xF0,  # 8
    0xF0, 0x90, 0xF0, 0x10, 0xF0,  # 9
    0xF0, 0x90, 0xF0, 0x90, 0x90,  # A
    0xE0, 0x90, 0xE0, 0x90, 0xE0,  # B
    0xF0, 0x80, 0x80, 0x80, 0xF0,  # C
    0xE0, 0x90, 0x90, 0x90, 0xE0,  # D
    0xF0, 0x80, 0xF0, 0x80, 0xF0,  # E
    0xF0, 0x80, 0xF0, 0x80, 0x80,  # F
]


class Chip8:
    def __init__(self, seed=None):
        self.memory = bytearray(MEM_SIZE)
        self.memory[FONT_START:FONT_START + len(FONTSET)] = bytes(FONTSET)
        self.v = bytearray(16)      # V0-VF registers
        self.i = 0                  # index register
        self.pc = ROM_START         # program counter
        self.stack = []             # call stack
        self.delay = 0              # delay timer
        self.sound = 0              # sound timer
        self.keys = [False] * 16    # hex keypad state
        self.display = bytearray(DISPLAY_W * DISPLAY_H)
        self.dw = DISPLAY_W         # active display width (subclasses may change)
        self.dh = DISPLAY_H         # active display height
        self.draw_flag = False      # set when display changed
        self.waiting_for_key = False  # FX0A blocked state
        self.rng = random.Random(seed)

    def load_rom(self, data, addr=ROM_START):
        self.memory[addr:addr + len(data)] = bytes(data)

    def cycle(self):
        """Fetch, decode and execute one instruction."""
        if self.waiting_for_key:
            for k, down in enumerate(self.keys):
                if down:
                    self.v[self._key_reg] = k
                    self.waiting_for_key = False
                    self.pc += 2
                    return
            return  # still waiting, pc does not advance
        op = (self.memory[self.pc] << 8) | self.memory[self.pc + 1]
        self.execute(op)

    def tick(self):
        """Decrement timers. The runner calls this at 60Hz."""
        if self.delay > 0:
            self.delay -= 1
        if self.sound > 0:
            self.sound -= 1

    # -- helpers -----------------------------------------------------

    @staticmethod
    def _x(op):
        return (op & 0x0F00) >> 8

    @staticmethod
    def _y(op):
        return (op & 0x00F0) >> 4

    @staticmethod
    def _nnn(op):
        return op & 0x0FFF

    @staticmethod
    def _nn(op):
        return op & 0x00FF

    def _draw_sprite(self, x, y, n):
        self.v[0xF] = 0
        for row in range(n):
            bits = self.memory[self.i + row]
            for col in range(8):
                if bits & (0x80 >> col):
                    px = (x + col) % self.dw
                    py = (y + row) % self.dh
                    idx = py * self.dw + px
                    if self.display[idx]:
                        self.v[0xF] = 1
                    self.display[idx] ^= 1
        self.draw_flag = True

    def execute(self, op):
        nnn = self._nnn(op)
        nn = self._nn(op)
        x = self._x(op)
        y = self._y(op)
        n = op & 0x000F

        if op == 0x00E0:
            self.display = bytearray(len(self.display))
            self.draw_flag = True
            self.pc += 2
        elif op == 0x00EE:
            self.pc = self.stack.pop()
        elif op & 0xF000 == 0x1000:
            self.pc = nnn
        elif op & 0xF000 == 0x2000:
            if len(self.stack) >= STACK_DEPTH:
                raise RuntimeError("stack overflow")
            self.stack.append(self.pc + 2)
            self.pc = nnn
        elif op & 0xF000 == 0x3000:
            self.pc += 4 if self.v[x] == nn else 2
        elif op & 0xF000 == 0x4000:
            self.pc += 4 if self.v[x] != nn else 2
        elif op & 0xF00F == 0x5000:
            self.pc += 4 if self.v[x] == self.v[y] else 2
        elif op & 0xF000 == 0x6000:
            self.v[x] = nn
            self.pc += 2
        elif op & 0xF000 == 0x7000:
            self.v[x] = (self.v[x] + nn) & 0xFF
            self.pc += 2
        elif op & 0xF000 == 0x8000:
            self._exec_8(op, x, y)
        elif op & 0xF00F == 0x9000:
            self.pc += 4 if self.v[x] != self.v[y] else 2
        elif op & 0xF000 == 0xA000:
            self.i = nnn
            self.pc += 2
        elif op & 0xF000 == 0xB000:
            self.pc = nnn + self.v[0]
        elif op & 0xF000 == 0xC000:
            self.v[x] = self.rng.randrange(256) & nn
            self.pc += 2
        elif op & 0xF000 == 0xD000:
            self._draw_sprite(self.v[x], self.v[y], n)
            self.pc += 2
        elif op & 0xF0FF == 0xE09E:
            self.pc += 4 if self.keys[self.v[x]] else 2
        elif op & 0xF0FF == 0xE0A1:
            self.pc += 4 if not self.keys[self.v[x]] else 2
        elif op & 0xF0FF == 0xF007:
            self.v[x] = self.delay
            self.pc += 2
        elif op & 0xF0FF == 0xF00A:
            self.waiting_for_key = True
            self._key_reg = x
        elif op & 0xF0FF == 0xF015:
            self.delay = self.v[x]
            self.pc += 2
        elif op & 0xF0FF == 0xF018:
            self.sound = self.v[x]
            self.pc += 2
        elif op & 0xF0FF == 0xF01E:
            self.i = (self.i + self.v[x]) & 0xFFF
            self.pc += 2
        elif op & 0xF0FF == 0xF029:
            self.i = FONT_START + self.v[x] * 5
            self.pc += 2
        elif op & 0xF0FF == 0xF033:
            val = self.v[x]
            self.memory[self.i] = val // 100
            self.memory[self.i + 1] = (val // 10) % 10
            self.memory[self.i + 2] = val % 10
            self.pc += 2
        elif op & 0xF0FF == 0xF055:
            self.memory[self.i:self.i + x + 1] = self.v[:x + 1]
            self.pc += 2
        elif op & 0xF0FF == 0xF065:
            self.v[:x + 1] = self.memory[self.i:self.i + x + 1]
            self.pc += 2
        else:
            raise RuntimeError(f"unknown opcode {op:04X} at {self.pc:04X}")

    def _exec_8(self, op, x, y):
        kind = op & 0x000F
        if kind == 0x0:
            self.v[x] = self.v[y]
        elif kind == 0x1:
            self.v[x] |= self.v[y]
        elif kind == 0x2:
            self.v[x] &= self.v[y]
        elif kind == 0x3:
            self.v[x] ^= self.v[y]
        elif kind == 0x4:
            total = self.v[x] + self.v[y]
            self.v[0xF] = 1 if total > 0xFF else 0
            self.v[x] = total & 0xFF
        elif kind == 0x5:
            self.v[0xF] = 1 if self.v[x] >= self.v[y] else 0
            self.v[x] = (self.v[x] - self.v[y]) & 0xFF
        elif kind == 0x6:
            # classic quirk: shift Vx itself, Vy ignored
            self.v[0xF] = self.v[x] & 0x1
            self.v[x] >>= 1
        elif kind == 0x7:
            self.v[0xF] = 1 if self.v[y] >= self.v[x] else 0
            self.v[x] = (self.v[y] - self.v[x]) & 0xFF
        elif kind == 0xE:
            # classic quirk: shift Vx itself, Vy ignored
            self.v[0xF] = (self.v[x] & 0x80) >> 7
            self.v[x] = (self.v[x] << 1) & 0xFF
        else:
            raise RuntimeError(f"unknown 8-opcode {op:04X} at {self.pc:04X}")
        self.pc += 2

contents.src/chip8/debugger.py:
"""Interactive debugger for CHIP-8 ROMs.

Commands:
  load <file>      load a rom (resets the cpu)
  step, s          execute one instruction
  run, c           run until a breakpoint or ctrl-c
  break <addr>, b  toggle a breakpoint at hex address
  regs             dump registers, I, PC, timers, stack
  mem <addr> [n]   dump n bytes of memory (default 16)
  dis [addr] [n]   disassemble n instructions (default 8) around addr/PC
  key <hex> on|off press or release a keypad key (for testing input opcodes)
  help             show this list
  quit, q          exit

Usage: python3 -m chip8.debugger roms/bounce.ch8
"""

import sys

from chip8.cpu import Chip8, DISPLAY_W, DISPLAY_H
from chip8.disasm import disassemble_range


class Debugger:
    def __init__(self):
        self.cpu = Chip8()
        self.breakpoints = set()
        self.running = True

    def load(self, path):
        self.cpu = Chip8()
        self.cpu.load_rom(open(path, "rb").read())
        self.breakpoints = set()
        print(f"loaded {path}")

    def cmd_step(self, args):
        pc = self.cpu.pc
        op = (self.cpu.memory[pc] << 8) | self.cpu.memory[pc + 1]
        from chip8.disasm import disassemble
        print(f"{pc:#06x}: {disassemble(op)}")
        self.cpu.cycle()
        self.cpu.tick()

    def cmd_run(self, args):
        print("running, ctrl-c to stop")
        try:
            while True:
                if self.cpu.pc in self.breakpoints:
                    print(f"hit breakpoint at {self.cpu.pc:#06x}")
                    break
                self.cpu.cycle()
                self.cpu.tick()
        except KeyboardInterrupt:
            print(f"\nstopped at {self.cpu.pc:#06x}")
        except RuntimeError as e:
            print(f"\nstopped with error: {e}")

    def cmd_break(self, args):
        if not args:
            bps = sorted(self.breakpoints)
            print("breakpoints:", " ".join(f"{b:#06x}" for b in bps) or "none")
            return
        addr = int(args[0], 16)
        if addr in self.breakpoints:
            self.breakpoints.remove(addr)
            print(f"removed breakpoint at {addr:#06x}")
        else:
            self.breakpoints.add(addr)
            print(f"breakpoint set at {addr:#06x}")

    def cmd_regs(self, args):
        c = self.cpu
        for i in range(0, 16, 4):
            print(" ".join(f"V{j:X}={c.v[j]:#04x}" for j in range(i, i + 4)))
        print(f"I={c.i:#05x} PC={c.pc:#06x} DT={c.delay} ST={c.sound}")
        print("stack:", " ".join(f"{a:#06x}" for a in c.stack) or "empty")

    def cmd_mem(self, args):
        addr = int(args[0], 16)
        n = int(args[1]) if len(args) > 1 else 16
        mem = self.cpu.memory
        for off in range(0, n, 8):
            chunk = mem[addr + off:addr + off + 8]
            hexs = " ".join(f"{b:02x}" for b in chunk)
            print(f"{addr + off:#06x}: {hexs}")

    def cmd_dis(self, args):
        addr = int(args[0], 16) if args else self.cpu.pc
        n = int(args[1]) if len(args) > 1 else 8
        for a, op, text in disassemble_range(self.cpu.memory, addr, n):
            marker = ">" if a == self.cpu.pc else " "
            bp = "*" if a in self.breakpoints else " "
            print(f"{marker}{bp}{a:#06x}: {op:04x}  {text}")

    def cmd_key(self, args):
        if len(args) != 2 or args[1] not in ("on", "off"):
            print("usage: key <hex> on|off  (e.g. key 4 on)")
            return
        k = int(args[0], 16)
        self.cpu.keys[k] = args[1] == "on"
        print(f"key {k:X} {'pressed' if self.cpu.keys[k] else 'released'}")

    def cmd_help(self, args):
        print(__doc__)

    def repl(self):
        cmds = {
            "step": self.cmd_step, "s": self.cmd_step,
            "run": self.cmd_run, "c": self.cmd_run,
            "break": self.cmd_break, "b": self.cmd_break,
            "regs": self.cmd_regs, "mem": self.cmd_mem,
            "dis": self.cmd_dis, "help": self.cmd_help,
            "key": self.cmd_key,
        }
        while self.running:
            try:
                line = input("(chip8) ").strip().split()
            except EOFError:
                break
            if not line:
                continue
            name, args = line[0], line[1:]
            if name in ("quit", "q"):
                break
            if name == "load":
                if args:
                    self.load(args[0])
                else:
                    print("usage: load <file>")
                continue
            fn = cmds.get(name)
            if fn:
                try:
                    fn(args)
                except Exception as e:
                    print(f"error: {e}")
            else:
                print(f"unknown command: {name} (try help)")


def main():
    dbg = Debugger()
    if len(sys.argv) == 2:
        dbg.load(sys.argv[1])
    dbg.repl()


if __name__ == "__main__":
    main()

contents.src/chip8/disasm.py:
"""Disassembler: turn raw opcode bytes into readable mnemonics."""


def disassemble(op):
    nnn = op & 0x0FFF
    nn = op & 0x00FF
    x = (op & 0x0F00) >> 8
    y = (op & 0x00F0) >> 4
    n = op & 0x000F

    if op == 0x00E0:
        return "CLS"
    if op == 0x00EE:
        return "RET"
    hi = op & 0xF000
    if hi == 0x1000:
        return f"JP {nnn:#05x}"
    if hi == 0x2000:
        return f"CALL {nnn:#05x}"
    if hi == 0x3000:
        return f"SE V{x:X}, {nn:#04x}"
    if hi == 0x4000:
        return f"SNE V{x:X}, {nn:#04x}"
    if op & 0xF00F == 0x5000:
        return f"SE V{x:X}, V{y:X}"
    if hi == 0x6000:
        return f"LD V{x:X}, {nn:#04x}"
    if hi == 0x7000:
        return f"ADD V{x:X}, {nn:#04x}"
    if hi == 0x8000:
        names = {
            0x0: "LD", 0x1: "OR", 0x2: "AND", 0x3: "XOR",
            0x4: "ADD", 0x5: "SUB", 0x6: "SHR", 0x7: "SUBN", 0xE: "SHL",
        }
        if n in names:
            return f"{names[n]} V{x:X}, V{y:X}"
        return f"DB {op:#06x}"
    if op & 0xF00F == 0x9000:
        return f"SNE V{x:X}, V{y:X}"
    if hi == 0xA000:
        return f"LD I, {nnn:#05x}"
    if hi == 0xB000:
        return f"JP V0, {nnn:#05x}"
    if hi == 0xC000:
        return f"RND V{x:X}, {nn:#04x}"
    if hi == 0xD000:
        return f"DRW V{x:X}, V{y:X}, {n}"
    if op & 0xF0FF == 0xE09E:
        return f"SKP V{x:X}"
    if op & 0xF0FF == 0xE0A1:
        return f"SKNP V{x:X}"
    if op & 0xF0FF == 0xF007:
        return f"LD V{x:X}, DT"
    if op & 0xF0FF == 0xF00A:
        return f"LD V{x:X}, K"
    if op & 0xF0FF == 0xF015:
        return f"LD DT, V{x:X}"
    if op & 0xF0FF == 0xF018:
        return f"LD ST, V{x:X}"
    if op & 0xF0FF == 0xF01E:
        return f"ADD I, V{x:X}"
    if op & 0xF0FF == 0xF029:
        return f"LD F, V{x:X}"
    if op & 0xF0FF == 0xF033:
        return f"LD B, V{x:X}"
    if op & 0xF0FF == 0xF055:
        return f"LD [I], V{x:X}"
    if op & 0xF0FF == 0xF065:
        return f"LD V{x:X}, [I]"
    return f"DB {op:#06x}"


def disassemble_range(memory, start, count):
    """Disassemble `count` instructions starting at address `start`."""
    lines = []
    addr = start
    for _ in range(count):
        op = (memory[addr] << 8) | memory[addr + 1]
        lines.append((addr, op, disassemble(op)))
        addr += 2
    return lines

contents.src/chip8/prof.py:
"""opcode profiler and hot block detector."""
from collections import Counter


class Profiler:
    def __init__(self, cpu):
        self.cpu = cpu
        self.op_counts = Counter()
        self.addr_counts = Counter()
        self.total = 0

    def step(self):
        pc = self.cpu.pc
        op = (self.cpu.memory[pc] << 8) | self.cpu.memory[pc + 1]
        # bucket by high nibble + low nibble pattern
        key = f"{op:04x}"
        self.op_counts[key] += 1
        self.addr_counts[pc] += 1
        self.total += 1
        self.cpu.cycle()

    def run(self, cycles):
        for _ in range(cycles):
            self.step()

    def top_ops(self, n=10):
        return self.op_counts.most_common(n)

    def top_addrs(self, n=10):
        return self.addr_counts.most_common(n)

    def hot_blocks(self, threshold=0.01, n=10):
        """basic blocks that eat more than threshold of cycles."""
        # a block starts after a jump/branch target or follows a branch
        blocks = Counter()
        addrs = sorted(self.addr_counts)
        if not addrs:
            return []
        block_start = addrs[0]
        for pc in addrs:
            op = (self.cpu.memory[pc] << 8) | self.cpu.memory[pc + 1]
            hi = op & 0xF000
            # branches end a block
            if hi in (0x1000, 0x2000, 0x3000, 0x4000, 0x5000, 0x9000, 0xA000):
                blocks[block_start] += self.addr_counts[pc]
                block_start = pc + 2
            elif op == 0x00EE:
                blocks[block_start] += self.addr_counts[pc]
                block_start = pc + 2
            else:
                blocks[block_start] += self.addr_counts[pc]
        cutoff = self.total * threshold
        hot = [(a, c) for a, c in blocks.items() if c >= cutoff]
        hot.sort(key=lambda x: -x[1])
        return hot[:n]

    def heatmap(self, width=64):
        """text heatmap of execution frequency per address."""
        if not self.addr_counts:
            return ""
        max_c = max(self.addr_counts.values())
        lo = min(self.addr_counts)
        hi = max(self.addr_counts)
        lines = []
        for addr in range(lo, hi + 1, 2):
            c = self.addr_counts.get(addr, 0)
            bar = "#" * int(width * c / max_c) if max_c else ""
            lines.append(f"{addr:04x} {c:8d} {bar}")
        return "\n".join(lines)

    def report(self):
        out = [f"total cycles: {self.total}", "top opcodes:"]
        for op, cnt in self.top_ops(10):
            pct = 100.0 * cnt / self.total if self.total else 0
            out.append(f"  {op} {cnt:8d} {pct:5.1f}%")
        out.append("hot blocks:")
        for addr, cnt in self.hot_blocks():
            pct = 100.0 * cnt / self.total if self.total else 0
            out.append(f"  {addr:04x} {cnt:8d} {pct:5.1f}%")
        return "\n".join(out)

