"""instruction trace logger."""
from .disasm import disassemble


class Tracer:
    def __init__(self, cpu, out=None, max_lines=None):
        self.cpu = cpu
        self.out = out
        self.max_lines = max_lines
        self.lines = []
        self.count = 0

    def step(self):
        pc = self.cpu.pc
        op = (self.cpu.memory[pc] << 8) | self.cpu.memory[pc + 1]
        text = disassemble(op)
        regs = " ".join(f"V{i:X}={self.cpu.v[i]:02x}" for i in range(16))
        line = f"{pc:04x} {op:04x} {text:<24} {regs} I={self.cpu.i:04x}"
        if self.out:
            self.out.write(line + "\n")
        else:
            self.lines.append(line)
        self.count += 1
        if self.max_lines and self.count >= self.max_lines:
            return False
        return True

    def run(self, cycles):
        for _ in range(cycles):
            if not self.step():
                break
            self.cpu.cycle()
        return self.lines

    def save(self, path):
        with open(path, "w") as f:
            for line in self.lines:
                f.write(line + "\n")

contents.src/chip8/tui.py:
"""Curses debugger TUI for CHIP-8 ROMs.

All rendering lives in pure functions (format_*, layout, render_frame)
so the whole UI is testable without a terminal. The curses loop at the
bottom is thin: it only draws the pre-rendered panes and maps keys to
debugger actions.

Keys:
  space/s  step one instruction        c      run until breakpoint/key
  b        toggle breakpoint at PC     w      add a watch expression
  x        drop the last watch         up/dn  scroll the memory view
  pgup/dn  scroll memory a page        q      quit
"""

import curses

from chip8.cpu import Chip8
from chip8.disasm import disassemble
from chip8.schip import SuperChip8, disassemble_schip


class WatchError(Exception):
    pass


class UiState:
    def __init__(self):
        self.breakpoints = set()
        self.watches = []     # list of expression strings
        self.mem_addr = 0x200
        self.running = False


# -- pure rendering --------------------------------------------------------

def _dis_fn(cpu):
    if isinstance(cpu, SuperChip8):
        return disassemble_schip
    return disassemble


def format_regs(cpu):
    """Register pane lines: V0-VF in rows of four, then I/PC/DT/ST/SP."""
    lines = []
    for base in range(0, 16, 4):
        lines.append(" ".join(f"V{i:X}={cpu.v[i]:02X}"
                              for i in range(base, base + 4)))
    lines.append(f"I={cpu.i:03X} PC={cpu.pc:04X} "
                 f"DT={cpu.delay:02X} ST={cpu.sound:02X}")
    lines.append(f"SP={len(cpu.stack)}")
    return lines


def format_disasm(cpu, breakpoints, before=6, after=12):
    """Disassembly centered on PC. '>' marks PC, '*' marks breakpoints."""
    dis = _dis_fn(cpu)
    start = max(0x200, cpu.pc - before * 2)
    lines = []
    addr = start
    for _ in range(before + after + 1):
        if addr > 0xFFE:
            break
        op = (cpu.memory[addr] << 8) | cpu.memory[addr + 1]
        cur = ">" if addr == cpu.pc else " "
        bp = "*" if addr in breakpoints else " "
        lines.append(f"{cur}{bp}{addr:04X}: {op:04X}  {dis(op)}")
        addr += 2
    return lines


def format_stack(cpu):
    """Call stack pane, top of stack first."""
    if not cpu.stack:
        return ["(empty)"]
    return [f"{i}: {addr:04X}" for i, addr in
            enumerate(reversed(cpu.stack))]


def format_mem(cpu, addr, rows=8, cols=8):
    """Hex dump with ascii gutter, clamped to memory bounds."""
    lines = []
    for r in range(rows):
        a = addr + r * cols
        if a >= len(cpu.memory):
            break
        chunk = cpu.memory[a:a + cols]
        hexs = " ".join(f"{b:02X}" for b in chunk)
        asc = "".join(chr(b) if 32 <= b < 127 else "." for b in chunk)
        lines.append(f"{a:04X}: {hexs:<{cols * 3 - 1}} |{asc}|")
    return lines


def format_breakpoints(breakpoints):
    if not breakpoints:
        return ["(none)"]
    return [f"{a:04X}" for a in sorted(breakpoints)]


def format_watches(cpu, watches):
    lines = []
    for expr in watches:
        try:
            val = eval_watch(cpu, expr)
            lines.append(f"{expr} = {val} ({val:#x})")
        except WatchError as e:
            lines.append(f"{expr} = <err: {e}>")
    return lines or ["(none)"]


def layout(w, h):
    """Pane rectangles for a terminal of w x h: name -> (x, y, w, h)."""
    w = max(w, 70)
    h = max(h, 28)  # keeps every pane at a positive height
    right_w = 36
    mem_h = 10
    mid = h - mem_h
    panes = {}
    panes["disasm"] = (0, 0, w - right_w - 1, mid)
    panes["regs"] = (w - right_w, 0, right_w, 7)
    panes["stack"] = (w - right_w, 7, right_w, 6)
    remaining = mid - 13
    watch_h = max(2, remaining * 2 // 3)
    bp_h = max(1, remaining - watch_h)
    panes["watches"] = (w - right_w, 13, right_w, watch_h)
    panes["breakpoints"] = (w - right_w, 13 + watch_h, right_w, bp_h)
    panes["mem"] = (0, mid, w, mem_h)
    panes["status"] = (0, h - 1, w, 1)
    return panes


def render_frame(cpu, ui, width=100, height=30):
    """Render every pane and clip lines to the pane rectangles."""
    panes = layout(width, height)
    content = {
        "disasm": format_disasm(cpu, ui.breakpoints),
        "regs": format_regs(cpu),
        "stack": format_stack(cpu),
        "watches": format_watches(cpu, ui.watches),
        "breakpoints": format_breakpoints(ui.breakpoints),
        "mem": format_mem(cpu, ui.mem_addr),
        "status": [status_line(cpu, ui)],
    }
    frame = {}
    for name, lines in content.items():
        _, _, pw, ph = panes[name]
        clipped = [line[:pw] for line in lines[:ph]]
        frame[name] = clipped
    return frame, panes


def status_line(cpu, ui):
    mode = "schip" if isinstance(cpu, SuperChip8) else "chip8"
    bps = len(ui.breakpoints)
    return (f"{mode} pc={cpu.pc:04X} bps={bps} watches={len(ui.watches)} "
            f"[space] step [c] run [b] break [w] watch [q] quit")


# -- watch expressions -----------------------------------------------------
# small recursive descent evaluator: numbers, V0-VF, I, PC, DT, ST, SP,
# the usual operators with c-like precedence, parens, unary minus/~.

_WATCH_OPS = ("<<", ">>", "+", "-", "*", "/", "%", "&", "|", "^", "~",
              "(", ")")


def _watch_lex(text):
    toks = []
    i = 0
    while i < len(text):
        ch = text[i]
        if ch.isspace():
            i += 1
        elif ch.isalpha() or ch == "_":
            j = i
            while j < len(text) and (text[j].isalnum() or text[j] == "_"):
                j += 1
            toks.append(("id", text[i:j].upper()))
            i = j
        elif ch.isdigit():
            j = i
            while j < len(text) and text[j].isalnum():
                j += 1
            word = text[i:j]
            try:
                toks.append(("num", int(word, 0)))
            except ValueError:
                raise WatchError(f"bad number {word}")
            i = j
        else:
            two = text[i:i + 2]
            if two in ("<<", ">>"):
                toks.append(("op", two))
                i += 2
            elif ch in "+-*/%&|^~()":
                toks.append(("op", ch))
                i += 1
            else:
                raise WatchError(f"bad character {ch!r}")
    return toks


def _watch_symbol(cpu, name):
    if len(name) == 2 and name[0] == "V" and name[1] in "0123456789ABCDEF":
        return cpu.v[int(name[1], 16)]
    if name == "I":
        return cpu.i
    if name == "PC":
        return cpu.pc
    if name == "DT":
        return cpu.delay
    if name == "ST":
        return cpu.sound
    if name == "SP":
        return len(cpu.stack)
    raise WatchError(f"unknown name {name}")


class _WatchParser:
    def __init__(self, toks, cpu):
        self.toks = toks
        self.cpu = cpu
        self.pos = 0

    def peek(self):
        return self.toks[self.pos] if self.pos < len(self.toks) else (None, None)

    def next(self):
        tok = self.peek()
        self.pos += 1
        return tok

    def expect_op(self, op):
        kind, val = self.next()
        if kind != "op" or val != op:
            raise WatchError(f"expected {op!r}")

    def parse(self):
        val = self.parse_or()
        if self.pos != len(self.toks):
            raise WatchError("trailing tokens")
        return val

    def parse_or(self):
        val = self.parse_xor()
        while self.peek() == ("op", "|"):
            self.next()
            val |= self.parse_xor()
        return val

    def parse_xor(self):
        val = self.parse_and()
        while self.peek() == ("op", "^"):
            self.next()
            val ^= self.parse_and()
        return val

    def parse_and(self):
        val = self.parse_shift()
        while self.peek() == ("op", "&"):
            self.next()
            val &= self.parse_shift()
        return val

    def parse_shift(self):
        val = self.parse_add()
        while True:
            if self.peek() == ("op", "<<"):
                self.next()
                val <<= self.parse_add()
            elif self.peek() == ("op", ">>"):
                self.next()
                val >>= self.parse_add()
            else:
                return val

    def parse_add(self):
        val = self.parse_mul()
        while True:
            if self.peek() == ("op", "+"):
                self.next()
                val += self.parse_mul()
            elif self.peek() == ("op", "-"):
                self.next()
                val -= self.parse_mul()
            else:
                return val

    def parse_mul(self):
        val = self.parse_unary()
        while True:
            kind, op = self.peek()
            if kind == "op" and op in ("*", "/", "%"):
                self.next()
                rhs = self.parse_unary()
                if op == "*":
                    val *= rhs
                elif op == "/":
                    if rhs == 0:
                        raise WatchError("division by zero")
                    val //= rhs
                else:
                    if rhs == 0:
                        raise WatchError("division by zero")
                    val %= rhs
            else:
                return val

    def parse_unary(self):
        kind, op = self.peek()
        if kind == "op" and op == "-":
            self.next()
            return -self.parse_unary()
        if kind == "op" and op == "~":
            self.next()
            return ~self.parse_unary()
        if kind == "op" and op == "+":
            self.next()
            return self.parse_unary()
        return self.parse_primary()

    def parse_primary(self):
        kind, val = self.next()
        if kind == "num":
            return val
        if kind == "id":
            return _watch_symbol(self.cpu, val)
        if (kind, val) == ("op", "("):
            out = self.parse_or()
            self.expect_op(")")
            return out
        raise WatchError("expected a value")


def eval_watch(cpu, text):
    """Evaluate a watch expression against the cpu state."""
    if not text.strip():
        raise WatchError("empty expression")
    toks = _watch_lex(text)
    return _WatchParser(toks, cpu).parse()


# -- thin curses loop ------------------------------------------------------

class TuiApp:
    def __init__(self, cpu):
        self.cpu = cpu
        self.ui = UiState()

    def step(self):
        pc = self.cpu.pc
        self.cpu.cycle()
        self.cpu.tick()
        return pc

    def run_until_stop(self, stdscr):
        # run with a timeout so a keypress can interrupt
        stdscr.timeout(16)
        while True:
            for _ in range(12):
                if self.cpu.pc in self.ui.breakpoints:
                    self.ui.running = False
                    return
                if getattr(self.cpu, "exited", False):
                    self.ui.running = False
                    return
                try:
                    self.cpu.cycle()
                except RuntimeError:
                    self.ui.running = False
                    return
                self.cpu.tick()
            self.draw(stdscr)
            if stdscr.getch() != -1:
                self.ui.running = False
                return

    def draw(self, stdscr):
        stdscr.erase()
        frame, panes = render_frame(self.cpu, self.ui,
                                    curses.COLS, curses.LINES)
        titles = {
            "disasm": "disassembly", "regs": "registers",
            "stack": "stack", "watches": "watches",
            "breakpoints": "breakpoints", "mem": "memory",
        }
        for name, lines in frame.items():
            if name == "status":
                continue
            x, y, pw, ph = panes[name]
            title = f"-- {titles[name]} --"
            try:
                stdscr.addnstr(y, x, title, pw)
                for i, line in enumerate(lines):
                    if i + 1 < ph:
                        stdscr.addnstr(y + 1 + i, x, line, pw)
            except curses.error:
                pass
        x, y, pw, _ = panes["status"]
        try:
            stdscr.addnstr(y, x, frame["status"][0], pw,
                           curses.A_REVERSE)
        except curses.error:
            pass
        stdscr.refresh()

    def prompt(self, stdscr, text):
        curses.echo()
        try:
            stdscr.addstr(curses.LINES - 1, 0, text)
            stdscr.clrtoeol()
            out = stdscr.getstr(curses.LINES - 1, len(text)).decode()
        except curses.error:
            out = ""
        finally:
            curses.noecho()
        return out

    def handle_key(self, stdscr, ch):
        if ch in (ord("q"), 27):
            return False
        if ch in (ord(" "), ord("s")):
            self.step()
        elif ch == ord("c"):
            self.ui.running = True
            self.run_until_stop(stdscr)
            stdscr.timeout(-1)
        elif ch == ord("b"):
            pc = self.cpu.pc
            if pc in self.ui.breakpoints:
                self.ui.breakpoints.remove(pc)
            else:
                self.ui.breakpoints.add(pc)
        elif ch == ord("w"):
            expr = self.prompt(stdscr, "watch: ")
            if expr.strip():
                self.ui.watches.append(expr.strip())
        elif ch == ord("x"):
            if self.ui.watches:
                self.ui.watches.pop()
        elif ch == curses.KEY_UP:
            self.ui.mem_addr = max(0, self.ui.mem_addr - 8)
        elif ch == curses.KEY_DOWN:
            self.ui.mem_addr = min(0x1000 - 64, self.ui.mem_addr + 8)
        elif ch == curses.KEY_PPAGE:
            self.ui.mem_addr = max(0, self.ui.mem_addr - 64)
        elif ch == curses.KEY_NPAGE:
            self.ui.mem_addr = min(0x1000 - 64, self.ui.mem_addr + 64)
        return True

    def run(self, stdscr):
        curses.curs_set(0)
        stdscr.timeout(-1)
        while True:
            self.draw(stdscr)
            if not self.handle_key(stdscr, stdscr.getch()):
                break


def main(argv):
    schip = "--schip" in argv
    args = [a for a in argv if a != "--schip"]
    if len(args) != 2:
        print("usage: python3 -m chip8.tui [--schip] <rom.ch8>")
        raise SystemExit(1)
    cpu = SuperChip8() if schip else Chip8()
    cpu.load_rom(open(args[1], "rb").read())
    curses.wrapper(TuiApp(cpu).run)


if __name__ == "__main__":
    import sys
    main(sys.argv)

contents.tests/test_opcodes.py:
"""Per-opcode unit tests for the CHIP-8 cpu."""

import os
import random
import sys

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

from chip8.cpu import Chip8


def step(*words, v=None, keys=None, mem=None, delay=None, cycles=1):
    """Load words at 0x200, apply setup, run cycles, return the cpu."""
    c = Chip8()
    out = bytearray()
    for w in words:
        out += bytes([w >> 8, w & 0xFF])
    c.load_rom(out)
    for i, val in (v or {}).items():
        c.v[i] = val
    for k in (keys or []):
        c.keys[k] = True
    for a, val in (mem or {}).items():
        c.memory[a] = val
    if delay is not None:
        c.delay = delay
    for _ in range(cycles):
        c.cycle()
    return c


def test_00e0_clears_display():
    c = Chip8()
    c.load_rom(bytes([0x00, 0xE0]))
    c.display[10] = 1
    c.cycle()
    assert sum(c.display) == 0 and c.pc == 0x202


def test_00ee_returns_from_subroutine():
    c = step(0x2204, 0x6001, 0x00EE, cycles=2)
    assert c.pc == 0x202 and c.stack == []


def test_1nnn_jumps():
    assert step(0x1300).pc == 0x300


def test_2nnn_calls_and_stacks():
    c = step(0x2300)
    assert c.pc == 0x300 and c.stack == [0x202]


def test_3xnn_skip():
    assert step(0x3205, v={2: 5}).pc == 0x204  # taken
    assert step(0x3205, v={2: 6}).pc == 0x202  # not taken


def test_4xnn_skip():
    assert step(0x4205, v={2: 9}).pc == 0x204  # taken
    assert step(0x4205, v={2: 5}).pc == 0x202  # not taken


def test_5xy0_skip():
    assert step(0x5120, v={1: 7, 2: 7}).pc == 0x204  # taken
    assert step(0x5120, v={1: 7, 2: 8}).pc == 0x202  # not taken


def test_6xnn_loads_byte():
    assert step(0x63AB).v[3] == 0xAB


def test_7xnn_adds_byte_wrapping():
    c = step(0x63FF, 0x7302, cycles=2)
    assert c.v[3] == 0x01 and c.v[0xF] == 0  # wraps, flag untouched


def test_8xy0_loads_reg():
    assert step(0x8120, v={2: 0x42}).v[1] == 0x42


def test_8xy1_or():
    assert step(0x8121, v={1: 0xF0, 2: 0x0F}).v[1] == 0xFF


def test_8xy2_and():
    assert step(0x8122, v={1: 0xF0, 2: 0x0F}).v[1] == 0x00


def test_8xy3_xor():
    assert step(0x8123, v={1: 0xFF, 2: 0x0F}).v[1] == 0xF0


def test_8xy4_add_with_carry():
    c = step(0x8124, v={1: 200, 2: 100})
    assert c.v[1] == 44 and c.v[0xF] == 1


def test_8xy4_add_without_carry():
    c = step(0x8124, v={1: 10, 2: 20})
    assert c.v[1] == 30 and c.v[0xF] == 0


def test_8xy5_sub_no_borrow():
    c = step(0x8125, v={1: 10, 2: 4})
    assert c.v[1] == 6 and c.v[0xF] == 1


def test_8xy5_sub_borrow():
    c = step(0x8125, v={1: 4, 2: 10})
    assert c.v[1] == 250 and c.v[0xF] == 0


def test_8xy6_shifts_vx_itself():
    # classic quirk: Vy ignored, Vx shifted, VF gets the old lsb
    c = step(0x8126, v={1: 0b101, 2: 0xFF})
    assert c.v[1] == 0b10 and c.v[0xF] == 1


def test_8xy7_subn():
    c = step(0x8127, v={1: 4, 2: 10})
    assert c.v[1] == 6 and c.v[0xF] == 1


def test_8xye_shifts_vx_itself():
    # classic quirk: Vy ignored, Vx shifted, VF gets the old msb
    c = step(0x812E, v={1: 0b10000001, 2: 0x00})
    assert c.v[1] == 0b10 and c.v[0xF] == 1


def test_9xy0_skip():
    assert step(0x9120, v={1: 1, 2: 2}).pc == 0x204  # taken
    assert step(0x9120, v={1: 1, 2: 1}).pc == 0x202  # not taken


def test_annn_sets_index():
    assert step(0xA321).i == 0x321


def test_bnnn_jumps_with_v0_offset():
    assert step(0xB300, v={0: 0x10}).pc == 0x310


def test_cxnn_random_masked():
    c = Chip8(seed=42)
    c.load_rom(bytes([0xC1, 0x0F]))
    c.cycle()
    expect = random.Random(42).randrange(256) & 0x0F
    assert c.v[1] == expect <= 0x0F


def test_dxyn_draws_and_collides():
    c = step(0xA300, 0x6000, 0x6100, 0xD011, mem={0x300: 0x80}, cycles=4)
    assert c.display[0] == 1 and c.v[0xF] == 0
    c.pc = 0x206  # draw the same sprite again
    c.cycle()
    assert c.display[0] == 0 and c.v[0xF] == 1  # xor erases, collision set


def test_ex9e_skips_when_key_down():
    c = step(0xE19E, v={1: 5}, keys=[5])
    assert c.pc == 0x204
    assert step(0xE19E, v={1: 5}).pc == 0x202


def test_exa1_skips_when_key_up():
    assert step(0xE1A1, v={1: 5}).pc == 0x204
    assert step(0xE1A1, v={1: 5}, keys=[5]).pc == 0x202


def test_fx07_reads_delay_timer():
    assert step(0xF107, delay=33).v[1] == 33


def test_fx0a_blocks_until_key():
    c = Chip8()
    c.load_rom(bytes([0xF1, 0x0A]))
    c.cycle()
    assert c.waiting_for_key and c.pc == 0x200
    c.cycle()
    assert c.waiting_for_key  # still waiting
    c.keys[9] = True
    c.cycle()
    assert not c.waiting_for_key and c.v[1] == 9 and c.pc == 0x202


def test_fx15_sets_delay_timer():
    assert step(0xF115, v={1: 60}).delay == 60


def test_fx18_sets_sound_timer():
    assert step(0xF118, v={1: 20}).sound == 20


def test_fx1e_adds_to_index():
    assert step(0xA300, 0xF11E, v={1: 0x10}, cycles=2).i == 0x310


def test_fx29_points_at_font():
    c = step(0xF129, v={1: 0xA})
    assert c.i == 0x050 + 0xA * 5
    assert c.memory[c.i] == 0xF0  # first byte of the A glyph


def test_fx33_stores_bcd():
    c = step(0xA300, 0xF133, v={1: 123}, cycles=2)
    assert (c.memory[0x300], c.memory[0x301], c.memory[0x302]) == (1, 2, 3)


def test_fx55_stores_registers_leaves_i():
    c = step(0xA300, 0xF255, v={0: 11, 1: 22, 2: 33}, cycles=2)
    assert (c.memory[0x300], c.memory[0x301], c.memory[0x302]) == (11, 22, 33)
    assert c.i == 0x300


def test_fx65_loads_registers_leaves_i():
    c = step(0xA300, 0xF265, mem={0x300: 11, 0x301: 22, 0x302: 33}, cycles=2)
    assert (c.v[0], c.v[1], c.v[2]) == (11, 22, 33)
    assert c.i == 0x300


def test_timers_tick_down_and_clamp():
    c = step(0x6000, delay=5)
    c.sound = 3
    c.tick()
    assert (c.delay, c.sound) == (4, 2)
    for _ in range(10):
        c.tick()
    assert (c.delay, c.sound) == (0, 0)  # never goes negative

