"""Assembler errors with line numbers and source context."""


class AsmError(Exception):
    def __init__(self, message, line=None, col=None, source_line=None,
                 filename=None):
        super().__init__(message)
        self.message = message
        self.line = line
        self.col = col
        self.source_line = source_line
        self.filename = filename

    def __str__(self):
        loc = ""
        if self.filename is not None:
            loc += f"{self.filename}:"
        if self.line is not None:
            loc += f"{self.line}:"
            if self.col is not None:
                loc += f"{self.col}:"
        head = f"{loc} error: {self.message}" if loc else \
            f"error: {self.message}"
        if self.source_line:
            caret = ""
            if self.col is not None:
                caret = "\n  " + " " * (self.col - 1) + "^"
            return f"{head}\n  {self.source_line.rstrip()}{caret}"
        return head


def error_at(message, token=None, line=None, text=None, filename=None):
    """Build an AsmError from a token or an explicit line number."""
    if token is not None:
        return AsmError(message, line=token.line, col=token.col,
                        source_line=text, filename=filename)
    return AsmError(message, line=line, source_line=text, filename=filename)

contents.tools/asm/expr.py:
"""Expressions with c-like operators and precedence.

Grammar (lowest to highest precedence):
  or        := xor ('|' xor)*
  xor       := and ('^' and)*
  and       := shift ('&' shift)*
  shift     := add (('<<' | '>>') add)*
  add       := mul (('+' | '-') mul)*
  mul       := unary (('*' | '/' | '%') unary)*
  unary     := ('-' | '~' | '+') unary | primary
  primary   := number | name | '$' | '(' or ')'

Names resolve against the symbol table (labels, EQU constants).
'$' is the address of the instruction being assembled, so 'JP $'
spins forever. Division is truncating; division by zero is an error.
"""

from .errors import AsmError


# nodes are tuples: ("num", v), ("id", name), ("neg", e), ("not", e),
# ("bin", op, left, right)


class ExprParser:
    def __init__(self, tokens, line, text, filename=None):
        self.tokens = tokens
        self.pos = 0
        self.line = line
        self.text = text
        self.filename = filename

    def fail(self, message, tok=None):
        if tok is None:
            tok = self.tokens[self.pos] if self.pos < len(self.tokens) \
                else None
        if tok is not None:
            raise AsmError(message, line=tok.line, col=tok.col,
                           source_line=self.text, filename=self.filename)
        raise AsmError(message, line=self.line, source_line=self.text,
                       filename=self.filename)

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) \
            else None

    def advance(self):
        tok = self.peek()
        self.pos += 1
        return tok

    def at_op(self, *ops):
        tok = self.peek()
        return tok is not None and tok.kind == "op" and tok.value in ops

    def parse(self):
        node = self.parse_or()
        if self.peek() is not None:
            self.fail(f"unexpected {self.peek().value!r} in expression")
        return node

    def parse_or(self):
        node = self.parse_xor()
        while self.at_op("|"):
            self.advance()
            node = ("bin", "|", node, self.parse_xor())
        return node

    def parse_xor(self):
        node = self.parse_and()
        while self.at_op("^"):
            self.advance()
            node = ("bin", "^", node, self.parse_and())
        return node

    def parse_and(self):
        node = self.parse_shift()
        while self.at_op("&"):
            self.advance()
            node = ("bin", "&", node, self.parse_shift())
        return node

    def parse_shift(self):
        node = self.parse_add()
        while self.at_op("<<", ">>"):
            op = self.advance().value
            node = ("bin", op, node, self.parse_add())
        return node

    def parse_add(self):
        node = self.parse_mul()
        while self.at_op("+", "-"):
            op = self.advance().value
            node = ("bin", op, node, self.parse_mul())
        return node

    def parse_mul(self):
        node = self.parse_unary()
        while self.at_op("*", "/", "%"):
            op = self.advance().value
            node = ("bin", op, node, self.parse_unary())
        return node

    def parse_unary(self):
        if self.at_op("-"):
            self.advance()
            return ("neg", self.parse_unary())
        if self.at_op("~"):
            self.advance()
            return ("not", self.parse_unary())
        if self.at_op("+"):
            self.advance()
            return self.parse_unary()
        return self.parse_primary()

    def parse_primary(self):
        tok = self.advance()
        if tok is None:
            self.fail("expected a value in expression")
        if tok.kind == "number":
            return ("num", tok.value)
        if tok.kind == "ident":
            return ("id", tok.value)
        if tok.kind == "lparen":
            node = self.parse_or()
            closing = self.advance()
            if closing is None or closing.kind != "rparen":
                self.fail("missing closing paren", tok)
            return node
        self.fail(f"unexpected {tok.value!r} in expression", tok)


def parse_expr(tokens, line, text, filename=None):
    """Parse a token list into an expression node."""
    return ExprParser(tokens, line, text, filename).parse()


def evaluate(node, symbols, pc=0, line=None, text=None, filename=None):
    """Evaluate an expression node to an int."""
    def fail(message):
        raise AsmError(message, line=line, source_line=text,
                       filename=filename)

    kind = node[0]
    if kind == "num":
        return node[1]
    if kind == "id":
        name = node[1]
        if name == "$":
            return pc
        if name in symbols:
            return symbols[name]
        fail(f"undefined symbol {name!r}")
    if kind == "neg":
        return -evaluate(node[1], symbols, pc, line, text, filename)
    if kind == "not":
        return ~evaluate(node[1], symbols, pc, line, text, filename)
    if kind == "bin":
        _, op, left, right = node
        lval = evaluate(left, symbols, pc, line, text, filename)
        rval = evaluate(right, symbols, pc, line, text, filename)
        if op == "+":
            return lval + rval
        if op == "-":
            return lval - rval
        if op == "*":
            return lval * rval
        if op == "/":
            if rval == 0:
                fail("division by zero")
            return lval // rval
        if op == "%":
            if rval == 0:
                fail("division by zero")
            return lval % rval
        if op == "&":
            return lval & rval
        if op == "|":
            return lval | rval
        if op == "^":
            return lval ^ rval
        if op == "<<":
            return lval << rval
        if op == ">>":
            return lval >> rval
        fail(f"unknown operator {op!r}")
    fail(f"bad expression node {node!r}")

contents.tools/asm/lexer.py:
"""Lexer for the chip-8 assembly language.

One line in, a list of tokens out. Comments start with ';' (ignored
inside strings and char literals). Numbers are decimal, 0x hex, 0b
binary, or 0o octal. 'A' is a char literal, "text" is a string (only
valid in DB). A leading '.' on a word is stripped: '.org' and 'org'
are the same directive.
"""

from .errors import AsmError


class Token:
    def __init__(self, kind, value, line, col):
        self.kind = kind      # ident, number, string, comma, colon,
        self.value = value    # lbracket, rbracket, lparen, rparen, op
        self.line = line
        self.col = col

    def __repr__(self):
        return f"Token({self.kind}, {self.value!r}, {self.line}:{self.col})"


class LexedLine:
    def __init__(self, lineno, tokens, text):
        self.lineno = lineno
        self.tokens = tokens
        self.text = text


def _is_ident_start(ch):
    return ch.isalpha() or ch == "_" or ch == "@"


def _is_ident_char(ch):
    return ch.isalnum() or ch == "_" or ch == "@"


def _read_number(text, i, line, col, src):
    j = i
    while j < len(text) and (text[j].isalnum() or text[j] == "_"):
        j += 1
    word = text[i:j].replace("_", "")
    try:
        if word[:2].lower() == "0x":
            value = int(word, 16)
        elif word[:2].lower() == "0b":
            value = int(word, 2)
        elif word[:2].lower() == "0o":
            value = int(word, 8)
        else:
            value = int(word, 10)
    except ValueError:
        raise AsmError(f"bad number {word!r}", line=line, col=col,
                       source_line=src)
    return Token("number", value, line, col), j


_ESCAPES = {"n": "\n", "t": "\t", "r": "\r", "0": "\0",
            "\\": "\\", "'": "'", '"': '"'}


def _read_char(text, i, line, col, src):
    # text[i] is the opening quote
    j = i + 1
    if j < len(text) and text[j] == "\\":
        esc = text[j + 1] if j + 1 < len(text) else ""
        if esc not in _ESCAPES:
            raise AsmError(f"bad escape '\\{esc}'", line=line, col=col,
                           source_line=src)
        value = ord(_ESCAPES[esc])
        j += 2
    elif j < len(text):
        value = ord(text[j])
        j += 1
    else:
        raise AsmError("unterminated char literal", line=line, col=col,
                       source_line=src)
    if j >= len(text) or text[j] != "'":
        raise AsmError("unterminated char literal", line=line, col=col,
                       source_line=src)
    return Token("number", value, line, col), j + 1


def _read_string(text, i, line, col, src):
    j = i + 1
    out = []
    while j < len(text) and text[j] != '"':
        if text[j] == "\\" and j + 1 < len(text):
            esc = text[j + 1]
            if esc not in _ESCAPES:
                raise AsmError(f"bad escape '\\{esc}'", line=line,
                               col=col, source_line=src)
            out.append(_ESCAPES[esc])
            j += 2
        else:
            out.append(text[j])
            j += 1
    if j >= len(text):
        raise AsmError("unterminated string", line=line, col=col,
                       source_line=src)
    return Token("string", "".join(out), line, col), j + 1


def lex_line(text, lineno, filename=None):
    """Lex one source line into tokens."""
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        col = i + 1
        if ch.isspace():
            i += 1
        elif ch == ";":
            break  # rest of the line is a comment
        elif ch == "." and i + 1 < n and _is_ident_start(text[i + 1]):
            # leading dot: directive marker, stripped
            j = i + 1
            while j < n and _is_ident_char(text[j]):
                j += 1
            tokens.append(Token("ident", text[i + 1:j], lineno, col))
            i = j
        elif _is_ident_start(ch):
            j = i
            while j < n and _is_ident_char(text[j]):
                j += 1
            tokens.append(Token("ident", text[i:j], lineno, col))
            i = j
        elif ch.isdigit():
            tok, i = _read_number(text, i, lineno, col, text)
            tokens.append(tok)
        elif ch == "'":
            tok, i = _read_char(text, i, lineno, col, text)
            tokens.append(tok)
        elif ch == '"':
            tok, i = _read_string(text, i, lineno, col, text)
            tokens.append(tok)
        elif ch == ",":
            tokens.append(Token("comma", ",", lineno, col))
            i += 1
        elif ch == ":":
            tokens.append(Token("colon", ":", lineno, col))
            i += 1
        elif ch == "[":
            tokens.append(Token("lbracket", "[", lineno, col))
            i += 1
        elif ch == "]":
            tokens.append(Token("rbracket", "]", lineno, col))
            i += 1
        elif ch == "(":
            tokens.append(Token("lparen", "(", lineno, col))
            i += 1
        elif ch == ")":
            tokens.append(Token("rparen", ")", lineno, col))
            i += 1
        elif text[i:i + 2] in ("<<", ">>"):
            tokens.append(Token("op", text[i:i + 2], lineno, col))
            i += 2
        elif ch in "+-*/%&|^~":
            tokens.append(Token("op", ch, lineno, col))
            i += 1
        elif ch == "$" and (i + 1 >= n or not text[i + 1].isalnum()):
            # bare $ means the current address
            tokens.append(Token("ident", "$", lineno, col))
            i += 1
        else:
            raise AsmError(f"unexpected character {ch!r}", line=lineno,
                           col=col, source_line=text, filename=filename)
    return tokens


def lex_source(src, filename=None):
    """Lex a whole source file into a list of LexedLine."""
    out = []
    for lineno, text in enumerate(src.splitlines(), 1):
        tokens = lex_line(text, lineno, filename)
        out.append(LexedLine(lineno, tokens, text))
    return out

