test("diffTapes reports a changed response body with a unified diff", () => {
  const req = ["POST", "/v1/chat/completions", { model: "x" }];
  const a = diffTape("a", [[...req, { content: "hello back" }]]);
  const b = diffTape("b", [[...req, { content: "hello there" }]]);
